public class Solution {
    public int minFlips(String expression) {
        int res = 0;
        Stack<Character> stack = new Stack<>();
        for (char c : expression.toCharArray()) {
            if (c == '(') {
                stack.push(c);
            } else if (c == ')') {
                while (!stack.isEmpty() && stack.peek() != '(') {
                    char op = stack.pop();
                    res += op == '&' ? 1 : 0;
                }
