public class Solution {
    public int maximumSum(int n, int index, int maxSum) {
        int[] nums = new int[n];
        for (int i = 0; i < n; i++) {
            if (i == 0) {
                nums[i] = 1;
            } else {
                nums[i] = nums[i - 1] + 1;
            }
        }

        Arrays.sort(nums);
        int sum = 0, max = 0;
        for (int i = n - 1; i >= 0; i--) {
            if (sum + nums[i] <= maxSum) {
                sum += nums[i];
                max = nums[i];
            } else {
                break;
            }
        }

        return index < n ? nums[index] : max;
    }
}

