                res.add(pq.poll());
            }
            if (task[0] > time) {
                time = task[0];
            }
            pq.offer(task[2]);
        }

        while (!pq.isEmpty()) {
            res.add(pq.poll());
        }

        int[] result = new int[res.size()];
        for (int i = 0; i < res.size(); i++) {
            result[i] = res.get(i);
        }
        return result;
    }
