public class Solution {
    public int minWastedSpace(int[] packages, int[][] boxes) {
        Arrays.sort(packages);
        PriorityQueue<Integer> pq = new PriorityQueue<>((a, b) -> a - b);
        for (int[] box : boxes) {
            pq.offer(Arrays.stream(box).max().getAsInt());
        }

        int wasted = 0;
        int i = 0;
        while (!pq.isEmpty()) {
            int boxSize = pq.poll();
            while (i < packages.length && packages[i] <= boxSize) {
                i++;
            }
            if (i == packages.length) break;
            wasted += boxSize - packages[i-1];
        }

        return wasted % 1000000007;
    }
}

