public class Solution {
    public int reinitializePermutation(int n) {
        int operations = 0;
        boolean[] seen = new boolean[n];
        while (true) {
            int[] perm = new int[n];
            for (int i = 0; i < n; i++) {
                if (i % 2 == 0) {
                    perm[i] = i / 2;
                } else {
                    perm[i] = n / 2 + (i - 1) / 2;
                }
            }
            boolean changed = false;
            for (int i = 0; i < n; i++) {
                if (!seen[perm[i]]) {
                    seen[perm[i]] = true;
                } else {
                    changed = true;
                    break;
                }
            }
            if (!changed) {
                break;
            }
            operations++;
        }
        return operations;
    }
}

