public class Solution {
    public int robotSim(int[] commands, int[][] obstacles) {
        Map<String, Integer> directions = new HashMap<>();
        directions.put("north", 0);
        directions.put("east", 1);
        directions.put("south", 2);
        directions.put("west", 3);

        int x = 0;
        int y = 0;
        int maxDistanceSquared = 0;

        for (int command : commands) {
            if (command == -2) {
                if (directions.get("north") == 0) {
                    directions.put("north", 3);
                    directions.put("south", 2);
                    directions.put("west", 1);
                    directions.put("east", 0);
                } else {
                    directions.put("north", directions.get("north") - 1);
                }
            } else if (command == -1) {
                if (directions.get("east") == 0) {
                    directions.put("east", 3);
                    directions.put("west", 2);
                    directions.put("south", 1);
                    directions.put("north", 0);
                } else {
                    directions.put("east", directions.get("east") - 1);
                }
            } else if (command > 0) {
                for (int i = 0; i < command; i++) {
                    switch ((int) directions.getOrDefault("direction", 0)) {
                        case 0:
                            y++;
                            break;
                        case 1:
                            x++;
                            break;
                        case 2:
                            y--;
                            break;
                        case 3:
                            x--;
                            break;
                    }
                    for (int[] obstacle : obstacles) {
                        if (x == obstacle[0] && y == obstacle[1]) {
                            switch ((int) directions.getOrDefault("direction", 0)) {
                                case 0:
                                    y--;
                                    break;
                                case 1:
                                    x--;
                                    break;
                                case 2:
                                    y++;
                                    break;
                                case 3:
                                    x++;
                                    break;
                            }
                        }
                    }
                }
                maxDistanceSquared = Math.max(maxDistanceSquared, x * x + y * y);
            }
        }

        return maxDistanceSquared;
    }
}

