public class Solution {
    public int numMagicSquaresInside(int[][] grid) {
        int count = 0;
        for (int i = 0; i <= grid.length - 3; i++) {
            for (int j = 0; j <= grid[0].length - 3; j++) {
                if (isMagicSquare(grid, i, j)) {
                    count++;
                }
            }
        }
        return count;
    }

    public boolean isMagicSquare(int[][] grid, int rowStart, int colStart) {
        int sum = 0;
        for (int i = 0; i < 3; i++) {
            sum += grid[rowStart + i][colStart];
        }
        if (!isRowEqual(grid, rowStart, colStart, sum)) {
            return false;
        }
        for (int i = 0; i < 3; i++) {
            sum = 0;
            for (int j = 0; j < 3; j++) {
                sum += grid[rowStart][colStart + j];
            }
            if (!isRowEqual(grid, rowStart, colStart + j, sum)) {
                return false;
            }
        }
        sum = 0;
        for (int i = 0; i < 3; i++) {
            sum += grid[rowStart + i][colStart + i];
        }
        if (!isRowEqual(grid, rowStart, colStart, sum)) {
            return false;
        }
        sum = 0;
        for (int i = 0; i < 3; i++) {
            sum += grid[rowStart + 2 - i][colStart + i];
        }
        if (!isRowEqual(grid, rowStart, colStart, sum)) {
            return false;
        }
        return true;
    }

    public boolean isRowEqual(int[][] grid, int row, int col, int sum) {
        for (int i = 0; i < 3; i++) {
            if (grid[row][col + i] != sum - grid[row][col]) {
                return false;
            }
        }
        return true;
    }
}

