        Arrays.sort(people);
        PriorityQueue<Integer> queue = new PriorityQueue<>((a, b) -> b - a);
        for (int person : people) {
            queue.offer(person);
        }

        int boats = 0;
        while (!queue.isEmpty()) {
            int first = queue.poll();
            if (!queue.isEmpty() && queue.peek() <= limit - first) {
                queue.poll(); // second person
            } else {
                boats++;
            }
        }
        return boats;
    }
}

