public class Solution {
    public int maxIncreaseKeepingSkyline(int[][] grid) {
        int n = grid.length;
        int[] east = new int[n];
        int[] north = new int[n];
        for (int i = 0; i < n; i++) {
            Arrays.fill(east, i);
            Arrays.fill(north, i);
            for (int j = 0; j < n; j++) {
                east[i] = Math.max(east[i], grid[j][i]);
                north[i] = Math.max(north[i], grid[i][j]);
            }
        }

        int maxIncrease = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
