public class Solution {
    public int matrixScore(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;

        for (int i = 0; i < m; i++) {
            if (grid[i][0] == 0) {
                for (int j = 0; j < n; j++) {
                    grid[i][j] = 1 - grid[i][j];
                }
            }
        }

        int score = 0;
        for (int i = 0; i < m; i++) {
            score += (grid[i][0] == 1) ? (int)Math.pow(2, n-1) : 0;
            for (int j = 1; j < n; j++) {
                if (grid[i][j] == 0) {
                    score -= Math.pow(2, n-j-1);
                }
            }
        }

        return score;
    }
}

