public class Solution {
    public int[] sumOfDistances(int n, int[][] edges) {
        List<Integer>[] graph = new List[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] edge : edges) {
            graph[edge[0]].add(edge[1]);
            graph[edge[1]].add(edge[0]);
        }

        int[] ans = new int[n];
        dfs(0, -1, graph, ans);
        dfs(n - 1, n, graph, ans);

        return ans;
    }

    private void dfs(int node, int parent, List<Integer>[] graph, int[] ans) {
        for (int neighbor : graph[node]) {
            if (neighbor != parent) {
                dfs(neighbor, node, graph, ans);
                ans[neighbor] = ans[node] - 2 * (parent == -1 ? n : 1);
                ans[node] += parent == -1 ? n : 1;
            }
        }
    }
}

