public class Solution {
    public int amountOfTime(TreeNode root, int start) {
        int time = 0;
        boolean[] visited = new boolean[20000];
        dfs(root, start, visited, time);
        return time;
    }

    private void dfs(TreeNode node, int target, boolean[] visited, int time) {
        if (node == null) {
            return;
        }
        if (node.val == target) {
            time = 0;
        } else {
            time++;
        }
        visited[node.val] = true;
        if (node.left != null && !visited[node.left.val]) {
            dfs(node.left, target, visited, time + 1);
        }
        if (node.right != null && !visited[node.right.val]) {
            dfs(node.right, target, visited, time + 1);
        }
    }
}

