public class Solution {
    public int peopleAwareOfSecret(int n, int delay, int forget) {
        BigInteger MOD = new BigInteger("1000000007");
        long[] dp = new long[n + 1];
        Arrays.fill(dp, 0);
        dp[0] = 1;

        for (int i = 1; i <= n; i++) {
            if (i >= delay) {
                dp[i] += dp[i - delay];
            }
            if (i >= forget) {
                dp[i] -= dp[i - forget];
            }
            dp[i] = dp[i].mod(MOD).longValue();
        }

        return (int) dp[n];
    }
}

