public class Solution {
    public int validSubarraySize(int[] nums, int threshold) {
        PriorityQueue<Integer> queue = new PriorityQueue<>();
        for (int i = 0; i < nums.length; i++) {
            while (!queue.isEmpty() && queue.peek() <= threshold / (i + 1)) {
                queue.poll();
            }
            queue.offer(nums[i]);
