public class Solution {
    public long zeroFilledSubarray(int[] nums) {
        Map<Integer, Long> lastZeroIndex = new HashMap<>();
        long totalZeros = 0;

        for (int i = 0; i < nums.length; i++) {
            if (nums[i] == 0) {
                totalZeros++;
                if (!lastZeroIndex.containsKey(i)) {
                    lastZeroIndex.put(i, (long) i);
                }
            } else {
                if (lastZeroIndex.containsKey(i - 1)) {
                    long start = lastZeroIndex.get(i - 1);
                    for (int j = start; j <= i; j++) {
                        totalZeros += (i - j + 1);
                    }
                }
                lastZeroIndex.clear();
            }
        }

        if (!lastZeroIndex.isEmpty()) {
            long start = lastZeroIndex.get(0);
            for (long end = start; end < nums.length; end++) {
                totalZeros += (end - start + 1);
            }
        }

        return totalZeros;
    }
}

