public class Solution {
    public int longestIdealString(String s, int k) {
        Map<Character, Integer> lastSeen = new HashMap<>();
        int maxLen = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (!lastSeen.containsKey(c)) {
                lastSeen.put(c, i);
            } else {
                int diff = c - 'a';
                if (i > 0) {
                    diff = Math.abs(diff - (s.charAt(i - 1) - 'a'));
                }
                if (diff <= k) {
                    maxLen = Math.max(maxLen, i - lastSeen.get(c) + 1);
                } else {
                    lastSeen.clear();
                    lastSeen.put(c, i);
                    maxLen = Math.max(maxLen, 1);
                }
            }
        }
        return maxLen;
    }
}

