        while (!queue.isEmpty()) {
            int max = queue.poll();
            if (max > 0) {
                if (max >= 2) {
                    queue.add(max - 2);
                } else {
                    for (int i = 0; i < 3; i++) {
                        if (amount[i] > 0) {
                            amount[i]--;
