        long[] dp = new long[maxValue + 1];
        Arrays.fill(dp, 1);

        for (int i = 2; i <= maxValue; i++) {
            if (i % 2 == 0) {
                dp[i] = dp[i / 2];
            } else {
                dp[i] = 1;
            }

            for (int j = i + 1; j <= maxValue; j++) {
                if (j % i == 0) {
                    dp[j] = (dp[j] + dp[i]) % MOD;
                }
            }
        }

        long res = 0;
        for (int i = 1; i <= maxValue; i++) {
            res = (res + dp[i]) % MOD;
        }

        return (int) res;
    }
}

