public class Solution {
    public String smallestNumber(String pattern) {
        List<Integer> nums = new ArrayList<>();
        for (int i = 1; i <= 9; i++) {
            nums.add(i);
        }

        for (int i = 0; i < pattern.length() - 1; i++) {
            if (pattern.charAt(i) == 'I') {
                int j = nums.indexOf(Integer.parseInt(String.valueOf(nums.get(0))));
                while (j < nums.size()) {
                    if (Integer.parseInt(String.valueOf(nums.get(j))) > Integer.parseInt(String.valueOf(nums.get(i)))) {
