                    }
                    nums.remove(j);
                }
            } else {
                int j = nums.indexOf(Integer.parseInt(String.valueOf(nums.get(0))));
                while (j < nums.size()) {
                    if (Integer.parseInt(String.valueOf(nums.get(j))) < Integer.parseInt(String.valueOf(nums.get(i)))) {
                        break;
                    }
                    nums.remove(j);
                }
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int num : nums) {
            sb.append(num).append(' ');
        }
        return sb.toString().trim();
