public class Solution {
    public int[] smallestTrimmedNumbers(String[] nums, int[][] queries) {
        int m = nums[0].length();
        int n = nums.length;
        String[] trimmedNums = new String[n];

        for (int i = 0; i < n; i++) {
            trimmedNums[i] = nums[i].substring(nums[i].length() - queries[0][1]);
        }

        Arrays.sort(trimmedNums);

        int[] answer = new int[queries.length];

        for (int i = 0; i < queries.length; i++) {
            PriorityQueue<String> pq = new PriorityQueue<>((a, b) -> a.compareTo(b));

            for (String num : trimmedNums) {
                if (pq.size() <= queries[i][1]) {
                    pq.offer(num);
                } else {
                    if (!pq.peek().equals(num)) {
                        pq.poll();
                        pq.offer(num);
                    }
                }
            }

            answer[i] = Integer.parseInt(pq.peek()) - 1;
        }

        return answer;
    }
}

