        int n = grid[0].length;
        int[][] diff = new int[m][n];

        for (int i = 0; i < m; i++) {
            int onesRow = Arrays.stream(grid[i]).sum();
            int zerosRow = n - onesRow;

            for (int j = 0; j < n; j++) {
                int onesCol = Arrays.stream(Arrays.asList(grid[0], grid[1], grid[2])).stream().mapToInt(row -> row[j]).sum();
