public class Solution {
    public int findDaysTogether(String arriveAlice, String leaveAlice, String arriveBob, String leaveBob) {
        int[] daysPerMonth = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};

        DateTimeFormatter formatter = DateTimeFormatter.ofPattern("MM-dd");

        LocalDate startAlice = null;
        LocalDate endAlice = null;
        try {
            startAlice = LocalDate.parse(arriveAlice + "-01", formatter);
            endAlice = LocalDate.parse(leaveAlice + "-01", formatter);
        } catch (DateTimeParseException e) {
            return 0;
        }

        LocalDate startBob = null;
        LocalDate endBob = null;
        try {
            startBob = LocalDate.parse(arriveBob + "-01", formatter);
            endBob = LocalDate.parse(leaveBob + "-01", formatter);
        } catch (DateTimeParseException e) {
            return 0;
        }

        int daysAliceInRome = (int) ((endAlice.toEpochDay() - startAlice.toEpochDay()) / (1000 * 60 * 60 * 24));
        int daysBobInRome = (int) ((endBob.toEpochDay() - startBob.toEpochDay()) / (1000 * 60 * 60 * 24));

        int overlapStart = Math.max(startAlice.toEpochDay(), startBob.toEpochDay());
        int overlapEnd = Math.min(endAlice.toEpochDay(), endBob.toEpochDay());

        int daysTogether = (overlapEnd - overlapStart) / (1000 * 60 * 60 * 24);

        return daysAliceInRome + daysBobInRome - daysTogether;
    }
}

