public class Solution {
    public List<List<String>> mostPopularCreator(String[] creators, String[] ids, int[] views) {
        Map<String, Integer> creatorViews = new HashMap<>();
        Map<String, Integer> idViews = new HashMap<>();

        for (int i = 0; i < creators.length; i++) {
            if (!creatorViews.containsKey(creators[i])) {
                creatorViews.put(creators[i], views[i]);
            } else {
                creatorViews.put(creators[i], creatorViews.get(creators[i]) + views[i]);
            }
            idViews.put(ids[i], views[i]);
        }

        List<List<String>> result = new ArrayList<>();
        int maxViews = 0;
        for (Map.Entry<String, Integer> entry : creatorViews.entrySet()) {
            if (entry.getValue() > maxViews) {
                maxViews = entry.getValue();
                result.clear();
                result.add(Arrays.asList(entry.getKey(), getMostViewedId(idViews, entry.getKey())));
            } else if (entry.getValue() == maxViews) {
                result.add(Arrays.asList(entry.getKey(), getMostViewedId(idViews, entry.getKey())));
            }
        }

        return result;
    }

    private String getMostViewedId(Map<String, Integer> idViews, String creator) {
        List<Map.Entry<String, Integer>> list = new ArrayList<>(idViews.entrySet());
        list.sort((o1, o2) -> o1.getValue().compareTo(o2.getValue()));
        for (Map.Entry<String, Integer> entry : list) {
            if (entry.getKey().startsWith(creator)) {
                return entry.getKey();
            }
        }
        return "";
    }
}

