                int profit = amount[neighbor];
                if (profit > 0) {
                    profit /= 2;
                } else {
                    profit += Math.abs(profit);
                }
                dp[node] = Math.max(dp[node], profit + dp[neighbor]);
                maxProfit = Math.max(maxProfit, dp[node]);
            }
        }
    }
}

