import java.util.Map;

public class Solution {
    public long dividePlayers(int[] skill) {
        int n = skill.length;
        Map<Integer, Integer> map = new HashMap<>();
        for (int i : skill) {
            map.put(i, map.getOrDefault(i, 0) + 1);
        }

        int totalSkill = 0;
        for (Map.Entry<Integer, Integer> entry : map.entrySet()) {
            if ((n / 2) % entry.getValue() != 0) {
                return -1;
            }
            totalSkill += entry.getKey() * entry.getValue();
        }

        long sumOfChemistry = 0;
        int left = n / 2;
        for (int i : skill) {
            if (left > map.get(i)) {
                sumOfChemistry += (long) Math.pow(i, 2);
            } else {
                sumOfChemistry += (long) Math.pow(i, 2) * (n - left);
            }
            map.put(i, map.get(i) - 1);
            if (--left == 0) break;
        }

        return totalSkill / n + sumOfChemistry;
    }
}

