import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

public class Solution {
    public int minCost(int[] nums, int[] cost) {
        int n = nums.length;
        List<int[]> list = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            list.add(new int[]{nums[i], cost[i]});
        }
        list.sort(Comparator.comparingInt(a -> a[1]));

        int totalCost = 0;
        int target = list.get(0)[0];
        for (int[] pair : list) {
            if (pair[0] > target) {
                totalCost += Math.abs(pair[0] - target) * pair[1];
                break;
            }
            totalCost += pair[1];
        }

        for (int i = 1; i < n; i++) {
            int diff = list.get(i)[0] - target;
            if (diff > 0) {
                totalCost += diff * list.get(i)[1];
            } else {
                totalCost -= diff * list.get(i)[1];
            }
        }

        return totalCost;
    }
}

