public class Solution {
    public long makeIntegerBeautiful(long n, int target) {
        List<Long> beautifulNumbers = new ArrayList<>();
        for (long i = 1; ; i++) {
            long sumOfDigits = getSumOfDigits(i);
            if (sumOfDigits > target) {
                break;
            }
            beautifulNumbers.add(i);
        }
        for (int i = beautifulNumbers.size() - 1; i >= 0; i--) {
            if (n + beautifulNumbers.get(i) <= n) {
                return beautifulNumbers.get(i);
            }
        }
        return 0L;
    }

    private long getSumOfDigits(long number) {
        BigInteger bi = BigInteger.valueOf(number);
        List<Character> digits = new ArrayList<>();
        while (bi.compareTo(BigInteger.ONE) >= 0) {
            digits.add(0, bi.mod(BigInteger.TEN).intValue() + '0');
            bi = bi.divide(BigInteger.TEN);
        }
        long sumOfDigits = 0;
        for (Character digit : digits) {
            sumOfDigits += digit - '0';
        }
        return sumOfDigits;
    }
}

