public class Solution {
    static class SegTree {
        int[] tree;
        int n;

        public SegTree(int n) {
            this.n = n;
            tree = new int[4 * n];
        }

        public void update(int i, int val) {
            i += n;
            tree[i] = val;
            while (i > 1) {
                i /= 2;
                tree[i] = Math.max(tree[2 * i], tree[2 * i + 1]);
            }
        }

        public int query(int l, int r) {
            l += n;
            r += n;
            int res = Integer.MIN_VALUE;
            while (l < r) {
                if ((l & 1) == 0) {
                    l /= 2;
                } else {
                    l++;
                }
                if ((r & 1) == 1) {
                    r--;
                } else {
                    r /= 2;
                }
                res = Math.max(res, tree[l]);
            }
            return res;
        }
    }

    public int longestSubsequence(int[] nums, int k) {
        Arrays.sort(nums);
        SegTree segTree = new SegTree(nums.length);
        int maxLen = 0;
        for (int i = 0; i < nums.length; i++) {
            int j = binarySearch(nums, i + 1, nums[i] + k);
            if (j > i) {
                maxLen = Math.max(maxLen, j - i);
                segTree.update(i, nums[j]);
            }
        }
        return maxLen;
    }

    public int binarySearch(int[] nums, int start, int end) {
        while (start < end) {
            int mid = (start + end) / 2;
            if (nums[mid] <= end - k) {
                start = mid + 1;
            } else {
                end = mid;
            }
        }
        return start;
    }
}

