public class Solution {
    public int numberOfGoodPaths(int[] vals, int[][] edges) {
        int n = vals.length;
        List<int[]> graph = new ArrayList<>();
        for (int[] edge : edges) {
            graph.add(new int[]{edge[0], edge[1]});
            graph.add(new int[]{edge[1], edge[0]}); // undirected
        }
        Arrays.sort(graph.toArray(), Comparator.comparingInt(a -> a[0]));
        Map<Integer, List<Integer>> tree = new HashMap<>();
        for (int[] edge : graph) {
            if (!tree.containsKey(edge[0])) {
                tree.put(edge[0], new ArrayList<>());
            }
            if (!tree.containsKey(edge[1])) {
                tree.put(edge[1], new ArrayList<>());
            }
            tree.get(edge[0]).add(edge[1]);
            tree.get(edge[1]).add(edge[0]);
        }
        int[] parent = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
        }
        for (int i = 0; i < n; i++) {
            for (int j : tree.get(i)) {
                if (parent[j] > parent[i]) {
                    parent[j] = parent[i];
                } else if (parent[i] > parent[j]) {
                    parent[i] = parent[j];
                }
            }
        }
        int[] valParent = new int[n];
        for (int i = 0; i < n; i++) {
            valParent[parent[i]]++;
        }
        Map<Integer, Integer> valCount = new HashMap<>();
        for (int i : tree.values()) {
            for (int j : i) {
                if (!valCount.containsKey(vals[j])) {
                    valCount.put(vals[j], 0);
                }
                valCount.put(vals[j], valCount.getOrDefault(vals[j], 0) + 1);
            }
        }
        int res = 0;
        for (Map.Entry<Integer, Integer> entry : valCount.entrySet()) {
            if (entry.getValue() == n - 1) {
                res++;
            } else {
                res += entry.getValue();
            }
        }
        return res;
    }
}

