public class Solution {
    public int mostBooked(int n, int[][] meetings) {
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        for (int[] meeting : meetings) {
            pq.offer(meeting);
        }

        int maxRoom = 0;
        int maxMeetings = 0;
        int currentRoom = 0;
        int currentMeetings = 0;

        while (!pq.isEmpty()) {
            int[] meeting = pq.poll();
