public class Solution {
    public ListNode removeNodes(ListNode head) {
        if (head == null) return null;

        ListNode dummy = new ListNode(0);
        dummy.next = head;
        ListNode prev = dummy;
        ListNode curr = head;

        while (curr != null) {
            boolean removed = false;
            while (curr.next != null && curr.next.val <= curr.val) {
                curr = curr.next;
                removed = true;
            }

            if (!removed) {
                prev.next = curr;
                prev = curr;
            } else {
                curr = curr.next;
            }
        }

        return dummy.next;
    }
}

