public class Solution {
    public int createSortedArray(int[] instructions) {
        int n = instructions.length;
        int[] nums = new int[n];
        int cost = 0;

        for (int i = 0; i < n; i++) {
            nums[i] = instructions[i];

            PriorityQueue<Integer> less = new PriorityQueue<>();
            PriorityQueue<Integer> greater = new PriorityQueue<>((a, b) -> a - b);

            for (int j = 0; j < i; j++) {
                if (nums[j] < instructions[i]) {
                    less.add(nums[j]);
                } else if (nums[j] > instructions[i]) {
