public class Solution {
    public int numWays(String[] words, String target) {
        int MOD = 1000000007;
        Map<Character, Integer>[] map = new Map[26];
        for (int i = 0; i < 26; i++) {
            map[i] = new HashMap<>();
        }
        for (String word : words) {
            for (char c : word.toCharArray()) {
                map[c - 'a'].put(c, map[c - 'a'].getOrDefault(c, 0) + 1);
            }
        }
        int res = 1;
        for (int i = 0; i < target.length(); i++) {
            char c = target.charAt(i);
            if (map[c - 'a'].getOrDefault(c, 0) == 0) {
                return 0;
            }
            map[c - 'a'].put(c, map[c - 'a'].get(c) - 1);
        }
        return res % MOD;
