public class Solution {
    public String smallestString(String s, int a, int b) {
        Set<String> set = new HashSet<>();
        set.add(s);

        while (true) {
            boolean changed = false;
            for (int i = 0; i < s.length(); i++) {
                if ((i & 1) == 1) {
                    char[] chars = s.toCharArray();
                    int sum = 0;
                    for (char c : chars) {
                        sum += c - '0';
                    }
                    sum += a;
                    while (sum > 9) {
                        sum -= 9;
                    }
                    chars[i] = (char) (sum + '0');
                    s = new String(chars);
                    changed = true;
                    break;
                }
            }

            if (!changed) {
                break;
            }

            char[] chars = s.toCharArray();
            for (int i = 0; i < b; i++) {
                char temp = chars[chars.length - 1];
                System.arraycopy(chars, 0, chars, 1, chars.length - 1);
                chars[0] = temp;
                s = new String(chars);
            }
        }

        return s;
    }
}

