public class Solution {
    public int visiblePoints(List<List<Integer>> points, int angle, List<Integer> location) {
        List<Double> angles = new ArrayList<>();
        for (List<Integer> point : points) {
            if (!location.equals(point)) {
                double dx = point.get(0) - location.get(0);
                double dy = point.get(1) - location.get(1);
                double angleInDegrees = Math.toDegrees(Math.atan2(dy, dx));
                angles.add(angleInDegrees);
            }
        }
        Collections.sort(angles);
        int maxVisible = 0;
        for (int i = 0; i < angles.size(); ) {
            int start = i;
            while (i + 1 < angles.size() && Math.abs(angles.get(i) - angles.get(i + 1)) <= angle) {
                i++;
            }
            maxVisible = Math.max(maxVisible, i - start + 1);
        }
        return maxVisible;
    }
}

