public class Solution {
    public int minimumMountainRemovals(int[] nums) {
        int n = nums.length;
        int left = 0, right = n - 1;
        for (int i = 1; i < n; i++) {
            if (nums[i] <= nums[i - 1]) {
                left = i;
                break;
            }
        }
        for (int i = n - 2; i >= 0; i--) {
            if (nums[i] >= nums[i + 1]) {
                right = i;
                break;
            }
        }
        int res = n - 1;
        for (int i = 0; i < left; i++) {
            res = Math.min(res, i);
        }
        for (int i = n - 1; i > right; i--) {
            res = Math.min(res, n - i - 1);
        }
        return res;
    }
}

