public class Solution {
    public List<Integer> busiestServers(int k, int[][] arrival, int[][] load) {
        List<Integer> result = new ArrayList<>();
        Map<Integer, Integer> serverBusyTime = new HashMap<>();
        for (int i = 0; i < k; i++) {
            serverBusyTime.put(i, 0);
        }

        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[1]));

        for (int i = 0; i < arrival.length; i++) {
            int[] request = {arrival[i][0], load[i][0], i};
            pq.offer(request);
        }

        while (!pq.isEmpty()) {
            int[] currentRequest = pq.poll();
            int serverId = currentRequest[2] % k;
            serverBusyTime.put(serverId, serverBusyTime.getOrDefault(serverId, 0) + 1);

            if (currentRequest[1] > 0) {
                pq.offer(new int[]{currentRequest[0] + currentRequest[1], currentRequest[1], currentRequest[2]});
            }
        }

        int maxBusy = Collections.max(serverBusyTime.values());
        for (Map.Entry<Integer, Integer> entry : serverBusyTime.entrySet()) {
            if (entry.getValue() == maxBusy) {
                result.add(entry.getKey());
            }
        }

        return result;
    }
}

