            if (!pq.isEmpty()) {
                int val2 = pq.poll();
                if (val1 > val2) {
                    alicePoints += val1;
                    bobPoints += val2;
                } else {
                    alicePoints += val2;
                    bobPoints += val1;
                }
            } else {
