import java.util.LinkedList;
public class Solution {
    public int minimumOneBitOperations(int n) {
        LinkedList<Integer> queue = new LinkedList<>();
        queue.add(n);
        int operations = 0;

        while (!queue.isEmpty()) {
            int current = queue.poll();
            if ((current & 1) == 1) {
                operations++;
                current >>= 1;
            } else {
                operations += (int) Math.ceil(Math.log(current) / Math.log(2));
            }
            queue.add(current);
        }

        return operations;
    }
}

