public class Solution {
    public int minStickers(String[] stickers, String target) {
        Map<Character, HashSet<Integer>> map = new HashMap<>();
        for (int i = 0; i < stickers.length; i++) {
            for (char c : stickers[i].toCharArray()) {
                if (!map.containsKey(c)) {
                    map.put(c, new HashSet<>());
                }
                map.get(c).add(i);
            }
        }

        int res = Integer.MAX_VALUE;
        boolean[] used = new boolean[stickers.length];
        dfs(map, target.toCharArray(), 0, "", used, res);

        return res == Integer.MAX_VALUE ? -1 : res;
    }

    private void dfs(Map<Character, HashSet<Integer>> map, char[] chars, int index, String path, boolean[] used, int res) {
        if (index >= chars.length) {
            res = Math.min(res, path.length());
            return;
        }
        for (int i = 0; i < chars[index]; i++) {
            if (!map.containsKey((char)chars[index])) {
                res = Integer.MAX_VALUE;
                return;
            }
        }
        for (int sticker : map.get((char)chars[index])) {
            if (used[sticker]) continue;
            used[sticker] = true;
            dfs(map, chars, index + 1, path + (char)chars[index], used, res);
            used[sticker] = false;
        }
    }
}

