            return true;
        }
        if (judge(a / d, b) && a % d == 0) {
            return true;
        }
        if (judge(b + d, c)) {
            return true;
        }
        if (judge(b - d, c)) {
            return true;
        }
        if (judge(b * d, c)) {
            return true;
        }
        if (judge(b / d, c) && b % d == 0) {
            return true;
        }
        return false;
    }
}

