public class Solution {
    public int scheduleCourse(int[][] courses) {
        Arrays.sort(courses, (a, b) -> a[1] - b[1]);
        PriorityQueue<Integer> pq = new PriorityQueue<>((a, b) -> b - a);
        int timeLimit = 0;
        for (int[] course : courses) {
            if (timeLimit + course[0] <= course[1]) {
                timeLimit += course[0];
                pq.offer(course[0]);
            } else if (!pq.isEmpty() && timeLimit + pq.peek() <= course[1]) {
                timeLimit += pq.poll();
                pq.offer(course[0]);
            }
        }
        return pq.size();
    }
}

