    public int triangleNumber(int[] nums) {
        Arrays.sort(nums);
        int count = 0;
        for (int i = 0; i < nums.length - 2; i++) {
            int k = i + 2;
            for (int j = i + 1; j < nums.length - 1; j++, k--) {
                while (k > j && nums[i] + nums[j] <= nums[k]) {
                    k--;
                }
                count += k - j;
            }
        }
        return count;
    }
}

