import com_github_leetcode.TreeNode;

public class Solution {
    public int longestUnivaluePath(TreeNode root) {
        int max = 0;
        if (root == null) return max;

        int[] maxLen = new int[1];
        dfs(root, root.val, maxLen);

        return maxLen[0];
    }

    private int dfs(TreeNode node, int val, int[] maxLen) {
        if (node == null) return 0;

        int left = dfs(node.left, val, maxLen);
        int right = dfs(node.right, val, maxLen);

        if (node.val == val) {
            maxLen[0] = Math.max(maxLen[0], left + right);
            return node.val == val ? 1 + Math.max(left, right) : 0;
        } else {
            return 0;
        }
    }
}

