import java.util.Arrays;

public class Solution {
    public int maxProfit(int k, int[] prices) {
        if (k == 0 || prices.length <= 1) return 0;

        Arrays.sort(prices);

        int n = prices.length;
        int[][] dp = new int[n][2];
        for (int i = 0; i < n; i++) {
            if (i == 0) {
                dp[i][0] = 0;
                dp[i][1] = -prices[0];
            } else {
                dp[i][0] = Math.max(dp[i-1][0], prices[i]);
                dp[i][1] = Math.max(dp[i-1][1], dp[i-1][0] - prices[i]);
            }
        }

        int maxProfit = 0;
        for (int i = k; i < n; i++) {
            if (i == k) {
                maxProfit = Math.max(maxProfit, dp[i][0] - prices[k-1]);
            } else {
                maxProfit = Math.max(maxProfit, dp[i][0] - prices[i-k]);
            }
        }

        return maxProfit;
    }
}

