import java.util.Arrays;

public class Solution {
    public int calculateMinimumHP(int[][] dungeon) {
        int m = dungeon.length;
        if (m == 0) return 1;
        int n = dungeon[0].length;

        int[][] dp = new int[m][n];
        for (int i = m - 1; i >= 0; i--) {
            for (int j = n - 1; j >= 0; j--) {
                if (i == m - 1 && j == n - 1) {
                    dp[i][j] = Math.max(1, 1 - dungeon[i][j]);
                } else if (i == m - 1) {
                    dp[i][j] = Math.max(1, 1 - dungeon[i][j] + dp[i][j + 1]);
                } else if (j == n - 1) {
                    dp[i][j] = Math.max(1, 1 - dungeon[i][j] + dp[i + 1][j]);
                } else {
                    int minHP = Math.min(dp[i + 1][j], dp[i][j + 1]) - dungeon[i][j];
                    if (minHP < 0) minHP = 1;
                    dp[i][j] = minHP;
                }
            }
        }

        return dp[0][0];
    }
}

