    private void wordBreakHelper(String s, int start, String current, Set<String> dict, List<String> result) {
        if (start == s.length()) {
            result.add(current);
            return;
        }
        for (int end = start + 1; end <= s.length(); end++) {
            String temp = s.substring(start, end);
            if (!dict.contains(temp)) continue;
            wordBreakHelper(s, end, current + " " + temp, dict, result);
        }
