import java.util.Map;

public class Solution {
    public int maxPoints(int[][] points) {
        if (points.length <= 2) {
            return points.length;
        }

        int max = 0;
        for (int i = 0; i < points.length; i++) {
            Map<String, Integer> map = new HashMap<>();
            int same = 1;
            for (int j = i + 1; j < points.length; j++) {
                if (points[i][0] == points[j][0] && points[i][1] == points[j][1]) {
                    same++;
                    continue;
                }
                int slope = get_slope(points[i], points[j]);
                map.put(String.valueOf(slope), map.getOrDefault(String.valueOf(slope), 0) + 1);
            }
            max = Math.max(max, same);
            for (int count : map.values()) {
                max = Math.max(max, count + same);
            }
        }

        return max;
    }

    private int get_slope(int[] p1, int[] p2) {
        if (p1[0] == p2[0]) {
            return Integer.MAX_VALUE;
        }
        return (p2[1] - p1[1]) * 10000 + (p2[0] - p1[0]);
    }
}

