import com_github_leetcode.left_right.Node;

public class Solution {
    public Node connect(Node root) {
        if (root == null) return root;

        Node current = root;
        while (current != null) {
            Node start = current;
            while (start != null) {
                if (start.left != null) {
                    start.left.next = start.right;
                    if (start.right.next != null) {
                        start.right.next = start.right.next.next;
                    }
                }
                if (start.right != null && start.right.next != null) {
                    start.right.next = start.right.next.next;
                }
                start = start.next;
            }
            current = current.left != null ? current.left : current.right;
        }

        return root;
    }
}

