public class Solution {
    public int makeArrayIncreasing(int[] arr1, int[] arr2) {
        Arrays.sort(arr2);
        int res = 0, i = 0;
        PriorityQueue<Integer> pq = new PriorityQueue<>();
        for (int x : arr1) {
            while (!pq.isEmpty() && pq.peek() < x) {
                pq.poll();
            }
            if (!pq.isEmpty()) {
                res += Math.abs(x - pq.peek());
            } else {
                res += x;
            }
            pq.offer(x);
        }
