public class Solution {
    public int minHeightShelves(int[][] books, int shelfWidth) {
        int n = books.length;
        int[] dp = new int[n + 1];
        int maxH = 0;

        for (int i = 1; i <= n; i++) {
            maxH = 0;
            int w = 0;
            for (int j = 0; j < i; j++) {
                w += books[j][0];
                maxH = Math.max(maxH, books[j][1]);
                if (w > shelfWidth) break;
            }
            dp[i] = maxH + (i == n ? 0 : dp[i - 1]);
        }

        return dp[n];
    }
}

