import java.util.Arrays;

public class Solution {
    public int maximumSum(int[] arr) {
        int n = arr.length;
        int maxSoFar = 0, maxEndingHere = 0;
        for (int i = 0; i < n; i++) {
            if (maxEndingHere <= 0)
                maxEndingHere = arr[i];
            else
                maxEndingHere += arr[i];
            maxSoFar = Math.max(maxSoFar, maxEndingHere);
        }
        int maxNoDelete = 0;
        for (int i = 1; i < n; i++) {
            maxNoDelete += arr[i - 1];
        }
        return Math.max(maxSoFar, maxNoDelete);
    }
}

