public class Solution {
    public List<TreeNode> delNodes(TreeNode root, int[] to_delete) {
        List<TreeNode> result = new ArrayList<>();
        TreeNode dummyRoot = new TreeNode(0);
        TreeNode current = dummyRoot;
        Set<Integer> set = new HashSet<>();
        for (int val : to_delete) {
            set.add(val);
        }

        helper(root, set, result, current);

        return result;
    }

    private void helper(TreeNode node, Set<Integer> set, List<TreeNode> result, TreeNode current) {
        if (node == null) {
            return;
        }

        boolean delete = set.contains(node.val);

        if (!delete) {
            current.right = node;
            current = current.right;
            result.add(node);
        } else {
            current.right = null;
        }

        helper(node.left, set, result, current);
        helper(node.right, set, result, current);
    }
}

