import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int longestWPI(int[] hours) {
        Map<Integer, Integer> map = new HashMap<>();
        int sum = 0;
        for (int i = 0; i < hours.length; i++) {
            sum += hours[i] > 8 ? 1 : -1;
            if (sum == 1) {
                for (int j = 0; j < i; j++) {
                    map.put(j, i);
                }
            } else if (sum > 1) {
                while (map.containsKey(i - 1)) {
                    int prevIndex = map.get(i - 1);
                    map.remove(prevIndex);
                    i = prevIndex;
                }
            }
        }
        return map.isEmpty() ? hours.length : map.get(map.size() - 1) - map.get(0) + 1;
    }
}

