public class Solution {
    public int maxLevelSum(TreeNode root) {
        if (root == null) return 0;

        int maxSum = Integer.MIN_VALUE, level = 1, sum = 0;
        List<TreeNode> queue = new ArrayList<>();
        queue.add(root);

