            int size = queue.size();
            sum = 0;

            for (int i = 0; i < size; i++) {
                TreeNode node = queue.remove(0);
                sum += node.val;

                if (node.left != null) queue.add(node.left);
                if (node.right != null) queue.add(node.right);
            }

            if (sum > maxSum) {
                maxSum = sum;
                level++;
            }
        }

        return level;
    }
}

