import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedList;
import java.util.List;
import java.util.Queue;

public class Solution {
    public int[] shortestAlternatingPath(int n, int[][] redEdges, int[][] blueEdges) {
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }

        for (int[] edge : redEdges) {
            graph.get(edge[0]).add(edge[1]);
        }

        for (int[] edge : blueEdges) {
            graph.get(edge[0]).add(edge[1]);
        }

        int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        int[][] colors = {{0, 1}, {1, 0}};

        int[] answer = new int[n];
        Arrays.fill(answer, -1);

        for (int i = 0; i < n; i++) {
            Queue<int[]> queue = new LinkedList<>();
            queue.add(new int[]{i, 0});

            while (!queue.isEmpty()) {
                int[] node = queue.poll();
                if (node[1] > answer[node[0]]) {
                    for (int j = 0; j < 4; j++) {
                        int newX = node[0] + directions[j][0];
                        int newColor = node[1] % 2;

                        if (newX >= 0 && newX < n) {
                            if ((node[1] / 2 == 0 && !graph.get(newX).contains(node[0])) || (node[1] / 2 == 1 && graph.get(newX).contains(node[0]))) {
                                continue;
                            }

                            for (int[] edge : redEdges) {
                                if (edge[1] == newX && edge[0] == node[0]) {
                                    newColor = 0;
                                    break;
                                }
                            }

                            for (int[] edge : blueEdges) {
                                if (edge[1] == newX && edge[0] == node[0]) {
                                    newColor = 1;
                                    break;
                                }
                            }

                            queue.add(new int[]{newX, colors[newColor][1]});
                            answer[newX] = Math.min(answer[newX], node[1] + 1);
                        }
                    }
                }
            }
        }

        return answer;
    }
}

