import java.util.Arrays;

public class Solution {
    public int[][] rotateGrid(int[][] grid, int k) {
        int m = grid.length;
        int n = grid[0].length;
        int[][] result = new int[m][n];

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                int layerIndex = (i + j) / 2;
                int newIndex = (layerIndex + k) % (m/2);
                result[newIndex][(n/2) - (j - i)] = grid[i][j];
            }
        }

        return result;
    }
}

