        int n = obstacles.length;
        int[] ans = new int[n];
        PriorityQueue<Integer> pq = new PriorityQueue<>((a, b) -> b - a);

        for (int i = 0; i < n; i++) {
            while (!pq.isEmpty() && pq.peek() < obstacles[i]) {
