import java.util.Arrays;

public class Solution {
    public long numberOfWeeks(int[] milestones) {
        int n = milestones.length;
        Arrays.sort(milestones);
        long weeks = 1;
        long totalMilestones = 0;
        for (int i = n - 1; i > n / 2; i--) {
            totalMilestones += milestones[i];
        }
        for (int i = 0; i < n / 2; i++) {
            totalMilestones += milestones[i] * 2;
        }
        weeks += totalMilestones / (long) n;
        return weeks + (totalMilestones % (long) n > 0 ? 1 : 0);
    }
}

