import java.math.BigInteger;
import java.util.ArrayList;
import java.util.List;

public class Solution {
    public long minimumPerimeter(long neededApples) {
        List<Long> apples = new ArrayList<>();
        long totalApples = 0;
        int sideLength = 1;
        while (totalApples < neededApples) {
            for (int i = -sideLength; i <= sideLength; i++) {
                for (int j = -sideLength; j <= sideLength; j++) {
                    if ((i * i + j * j) > totalApples) {
                        apples.add(BigInteger.valueOf((long) Math.pow(sideLength, 2)).subtract(BigInteger.valueOf(i * i).add(BigInteger.valueOf(j * j))).longValue());
                        totalApples += apples.get(apples.size() - 1);
                    }
                }
            }
            sideLength++;
        }
        return (int) ((Math.sqrt(8 * neededApples + 1) - 1) / 2) * 4;
    }
}

