import java.util.ArrayList;
import java.util.List;

public class Solution {
    public boolean checkMove(char[][] board, int rMove, int cMove, char color) {
        // Check if the cell is free
        if (board[rMove][cMove] != '.') return false;

        // Change the cell to the given color
        board[rMove][cMove] = color;

        // Check all directions for a good line
        for (int dr : new int[] {-1, 0, 1}) {
            for (int dc : new int[] {-1, 0, 1}) {
                if (Math.abs(dr) == Math.abs(dc)) continue; // skip diagonal

                int r = rMove;
                int c = cMove;

                List<Character> line = new ArrayList<>();

                while (true) {
                    line.add(board[r][c] == '.' ? 'F' : board[r][c]);

                    if (board[r][c] != color && !line.contains('F')) break; // found a good line

                    r += dr;
                    c += dc;

                    if (r < 0 || r >= 8 || c < 0 || c >= 8) break; // out of bounds
                }

                if (line.size() >= 3 && line.get(0) == color && line.get(line.size() - 1) == color) {
                    board[rMove][cMove] = '.'; // restore the cell to its original state
                    return true;
                }
            }
        }

        board[rMove][cMove] = '.'; // restore the cell to its original state
        return false;
    }
}

