import java.util.*;

public class Solution {
    public int countSubIslands(int[][] grid1, int[][] grid2) {
        int m = grid2.length;
        int n = grid2[0].length;
        int res = 0;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid2[i][j] == 1) {
                    boolean isSubIsland = true;
                    dfs(grid1, grid2, i, j);
                    if (!isSubIsland) {
                        res++;
                    }
                }
            }
        }

        return res;
    }

    private void dfs(int[][] grid1, int[][] grid2, int i, int j) {
        if (i < 0 || i >= grid2.length || j < 0 || j >= grid2[0].length || grid2[i][j] == 0) {
            return;
        }

        grid2[i][j] = 0; // mark as visited

        int m1 = grid1.length;
        int n1 = grid1[0].length;

        for (int x = -1; x <= 1; x++) {
            for (int y = -1; y <= 1; y++) {
                if ((x == 0 && y == 0) || i + x < 0 || i + x >= m1 || j + y < 0 || j + y >= n1) {
                    continue;
                }

                if (grid1[i + x][j + y] != grid2[i + x][j + y]) {
                    isSubIsland = false;
                    return;
                }
            }
        }
    }
}

