import java.text.ParseException;
import java.text.SimpleDateFormat;
import java.util.Date;

public class Solution {
    public int numberOfRounds(String loginTime, String logoutTime) {
        SimpleDateFormat sdf = new SimpleDateFormat("HH:mm");
        try {
            Date loginDate = sdf.parse(loginTime);
            Date logoutDate = sdf.parse(logoutTime);

            if (logoutDate.before(loginDate)) {
                logoutDate = sdf.parse("23:59"); // adjust to midnight
            }

            long loginTimeInMilliseconds = loginDate.getTime();
            long logoutTimeInMilliseconds = logoutDate.getTime();

            int roundsPlayed = 0;
            for (long timeInMilliseconds = loginTimeInMilliseconds; timeInMilliseconds <= logoutTimeInMilliseconds; ) {
                if (timeInMilliseconds < loginTimeInMilliseconds) {
                    timeInMilliseconds += 900000; // adjust to next round
                }
                if (timeInMilliseconds >= loginTimeInMilliseconds && timeInMilliseconds % 900000 < 90000) {
                    roundsPlayed++;
                }
                timeInMilliseconds += 90000;
            }

            return roundsPlayed;
        } catch (ParseException e) {
            throw new RuntimeException(e);
        }
    }
}

