import java.util.List;

public class Solution {
    public List<List<Long>> splitPainting(int[][] segments) {
        List<List<Long>> painting = new ArrayList<>();
        long sum = 0;
        for (int i = 0; i < segments.length; i++) {
            if (i == 0 || segments[i][0] > segments[i - 1][1]) {
                if (i > 0) {
                    painting.add(Arrays.asList(segments[i - 1][0], segments[i - 1][1], sum));
                }
                sum = segments[i][2];
            } else {
                sum += segments[i][2] - segments[i - 1][2];
            }
        }
        if (sum > 0) {
            painting.add(Arrays.asList(segments[segments.length - 1][0], segments[segments.length - 1][1], sum));
        }
        return painting;
    }
}

