public class Solution {
    public int minTime(int n, int[][] roads) {
        List<List<int[]>> graph = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }

        for (int[] road : roads) {
            graph.get(road[0]).add(new int[]{road[1], road[2]});
            graph.get(road[1]).add(new int[]{road[0], road[2]});
        }

        int[][] dp = new int[n][n];
        for (int i = 0; i < n; i++) {
            Arrays.fill(dp[i], Integer.MAX_VALUE);
        }
        dp[0][0] = 0;

        for (int k = 0; k < n; k++) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (dp[i][k] != Integer.MAX_VALUE && dp[k][j] != Integer.MAX_VALUE) {
                        int time = Math.min(dp[i][k], dp[k][j]) + roads[roads.length - 1][2];
                        if (time < dp[i][j]) {
                            dp[i][j] = time;
                        }
                    }
                }
            }
        }

        long res = 0;
        for (int i = 0; i < n; i++) {
            res += dp[0][i];
        }
        return (int) (res % (1e9 + 7));
    }
