import java.util.Map;

public class Solution {
    public int countGoodNumbers(long n) {
        BigInteger MOD = new BigInteger("1000000007");
        Map<Integer, BigInteger> dp = new HashMap<>();
        dp.put(0, BigInteger.ONE);

        for (int i = 1; i <= 9; i++) {
            if (i % 2 == 0 || isPrime(i)) {
                for (int j = 0; j < n; j++) {
                    if (j >= 1) {
                        dp.put(j, dp.getOrDefault(j - 1, BigInteger.ZERO).add(dp.getOrDefault(j, BigInteger.ZERO)));
                    }
                    if (i % 2 == 0 || isPrime(i)) {
                        dp.put(j + 1, dp.getOrDefault(j + 1, BigInteger.ZERO).add(dp.get(j)));
                    }
                }
            }
        }

        return dp.get(n).mod(MOD).intValue();
    }

    public boolean isPrime(int n) {
        if (n <= 1) {
            return false;
        }
        for (int i = 2; i * i <= n; i++) {
            if (n % i == 0) {
                return false;
            }
        }
        return true;
    }
}

