import java.util.Arrays;

public class Solution {
    public int minSpaceWastedKResizing(int[] arr, int k) {
        int n = arr.length;
        int[][] dp = new int[n][k + 1];
        Arrays.fill(dp[0], Integer.MAX_VALUE);
        dp[0][0] = 0;

        for (int i = 1; i < n; i++) {
            for (int j = Math.min(i, k); j >= 0; j--) {
                int wasted = Integer.MAX_VALUE;
                if (j > 0) {
                    wasted = dp[i - 1][j - 1] + arr[i] - (i == 0 ? 0 : arr[i - 1]);
                }
                for (int m = i; m >= 0; m--) {
                    int newWasted = Math.max(wasted, dp[m - 1][j] + arr[i] - arr[m]);
                    if (m > 0) {
                        newWasted = Math.min(newWasted, dp[m - 1][j] + i - m);
                    }
                    dp[i][j] = Math.min(dp[i][j], newWasted);
                }
            }
        }

        return dp[n - 1][k];
    }
}

