public class Solution {
    public long maxProduct(String s) {
        int n = s.length();
        Map<Integer, Integer> map = new HashMap<>();
        for (int i = 0; i < n; i++) {
            if (!map.containsKey(i)) {
                map.put(i, 1);
            } else {
                map.put(i, map.get(i) + 1);
            }
            if (!map.containsKey(n - i - 1)) {
                map.put(n - i - 1, 1);
            } else {
                map.put(n - i - 1, map.get(n - i - 1) + 1);
            }
        }

        long maxProduct = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i; j < n; j++) {
                if (map.getOrDefault(i, 0) % 2 == 1 && map.getOrDefault(j, 0) % 2 == 1) {
                    int k = i;
                    while (k <= j && s.charAt(k) == s.charAt(n - k - 1)) {
                        k++;
                    }
                    if (k > j) {
                        continue;
                    }
                    int l = n - k;
                    while (l >= j && s.charAt(l) == s.charAt(k)) {
                        l--;
                    }
                    if (l < j) {
                        continue;
                    }
                    maxProduct = Math.max(maxProduct, (long) (k - i + 1) * (l - j + 1));
                }
            }
        }

        return maxProduct;
    }
}

