import java.util.*;

public class Solution {
    public int minCost(int maxTime, int[][] edges, int[] passingFees) {
        int n = edges.length;
        List<List<int[]>> graph = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            graph.get(edge[0]).add(new int[]{edge[1], edge[2]});
            graph.get(edge[1]).add(new int[]{edge[0], edge[2]});
        }

        Map<Integer, Integer> timeToPass = new HashMap<>();
        for (int i = 0; i < n; i++) {
            timeToPass.put(i, passingFees[i]);
        }

        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[1] - b[1]);
        pq.offer(new int[]{0, maxTime});
        Map<Integer, Integer> dp = new HashMap<>();
        while (!pq.isEmpty()) {
            int time = pq.poll()[1];
            for (int[] edge : graph.get(pq.peek()[0])) {
                if (time >= edge[2]) {
                    int cost = timeToPass.getOrDefault(edge[0], 0) + time - edge[2];
                    if (!dp.containsKey(edge[0]) || dp.get(edge[0]) > cost) {
                        dp.put(edge[0], cost);
                        pq.offer(new int[]{edge[0], time - edge[2]});
                    }
                } else {
                    break;
                }
            }
        }

        return dp.getOrDefault(n - 1, -1);
    }
}

