import java.util.Arrays;

public class Solution {
    public long maxAlternatingSum(int[] nums) {
        int n = nums.length;
        long even = 0, odd = 0;

        for (int i = 0; i < n; i++) {
            if ((i & 1) == 0) { // even index
                even += nums[i];
            } else { // odd index
                odd += nums[i];
            }
        }

        long maxSum = Math.max(even, odd);

        for (int i = 1; i < n; i++) {
            if ((i & 1) == 0) { // even index
                even -= nums[i - 1];
                odd += nums[i];
                maxSum = Math.max(maxSum, Math.abs(even - odd));
            } else { // odd index
                even += nums[i];
                odd -= nums[i];
                maxSum = Math.max(maxSum, Math.abs(even - odd));
            }
        }

        return maxSum;
    }
}

