public class Solution {
    public int nearestExit(char[][] maze, int[] entrance) {
        int m = maze.length;
        int n = maze[0].length;
        boolean[][] visited = new boolean[m][n];

        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{entrance[0], entrance[1]});
        visited[entrance[0]][entrance[1]] = true;

        int steps = 0;
        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                int[] cell = queue.poll();
                if (cell[0] == 0 || cell[0] == m - 1 || cell[1] == 0 || cell[1] == n - 1) {
                    if ((cell[0] == 0 && cell[1] != 0) || (cell[0] == m - 1 && cell[1] != n - 1) || (cell[0] != 0 && cell[0] != m - 1 && cell[1] == 0) || (cell[0] != 0 && cell[0] != m - 1 && cell[1] == n - 1)) {
                        return steps + 1;
                    }
                }

                for (int[] dir : new int[][]{{-1, 0}, {1, 0}, {0, -1}, {0, 1}}) {
                    int x = cell[0] + dir[0];
                    int y = cell[1] + dir[1];
                    if (x >= 0 && x < m && y >= 0 && y < n && maze[x][y] == '.' && !visited[x][y]) {
                        queue.offer(new int[]{x, y});
                        visited[x][y] = true;
                    }
                }
            }
            steps++;
        }

        return -1;
    }
}

