public class Solution {
    public int[] findMode(TreeNode root) {
        List<Integer> list = new ArrayList<>();
        int maxCount = 0, mode = Integer.MIN_VALUE;
        inOrder(root, list);
        for (int i : list) {
            if (list.indexOf(i) == list.lastIndexOf(i)) {
                if ((list.size() - 1) / 2 < maxCount || i > mode) {
                    maxCount = (list.size() - 1) / 2;
                    mode = i;
                }
            } else {
                if (list.size() - 1 == list.indexOf(i) + list.lastIndexOf(i)) {
                    if ((list.size() - 1) / 2 < maxCount || i > mode) {
                        maxCount = (list.size() - 1) / 2;
                        mode = i;
                    }
                }
            }
        }
        int[] result = new int[maxCount];
        for (int i : list) {
            if (i == mode) {
                result[--maxCount] = i;
            }
        }
        return result;
    }

    private void inOrder(TreeNode root, List<Integer> list) {
        if (root != null) {
            inOrder(root.left, list);
            list.add(root.val);
            inOrder(root.right, list);
        }
    }
}

