import java.util.Arrays;

public class Solution {
    public int removeBoxes(int[] boxes) {
        int n = boxes.length;
        int[][] dp = new int[n][n];
        for (int i = 0; i < n; i++) {
            Arrays.fill(dp[i], -1);
        }
        return dfs(boxes, 0, n - 1, dp);
    }

    private int dfs(int[] boxes, int left, int right, int[][] dp) {
        if (left > right || boxes[left] != boxes[right]) {
            return 0;
        }
        if (dp[left][right] != -1) {
            return dp[left][right];
        }
        int res = (boxes[left] * boxes[left] + dfs(boxes, left + 1, right - 1, dp));
        for (int i = left; i < right; i++) {
            if (boxes[i] == boxes[left]) {
                res = Math.max(res, boxes[left] * boxes[left] + dfs(boxes, left, i, dp) + dfs(boxes, i + 1, right, dp));
            }
        }
        dp[left][right] = res;
        return res;
    }
}

