import java.math.BigInteger;

public class Solution {
    public String fractionAddition(String expression) {
        int i = 0, n = expression.length();
        List<int[]> fractions = new ArrayList<>();
        while (i < n) {
            if (expression.charAt(i) == '+') i++;
            else if (expression.charAt(i) == '-') {
                i++;
                fractions.add(new int[]{0, 0});
            }
            int j = i + 1;
            while (j < n && Character.isDigit(expression.charAt(j))) j++;
            int numerator = Integer.parseInt(expression.substring(i, j));
            i = j;
            if (expression.charAt(i) == '/') {
                i++;
                j = i + 1;
                while (j < n && Character.isDigit(expression.charAt(j))) j++;
                int denominator = Integer.parseInt(expression.substring(i, j));
                fractions.add(new int[]{numerator, denominator});
                i = j;
            }
        }
        BigInteger resultNumerator = BigInteger.ZERO, resultDenominator = BigInteger.ONE;
        for (int[] fraction : fractions) {
            BigInteger numerator = BigInteger.valueOf(fraction[0]), denominator = BigInteger.valueOf(fraction[1]);
            if (denominator.equals(BigInteger.ONE)) denominator = BigInteger.valueOf(1);
            BigInteger newNumerator = numerator.multiply(denominator).add(resultDenominator.multiply(numerator));
            BigInteger newDenominator = resultDenominator.multiply(denominator);
            if (!newNumerator.gcd(newDenominator).equals(BigInteger.ONE)) {
                int gcd = newNumerator.gcd(newDenominator).intValue();
                newNumerator = newNumerator.divide(BigInteger.valueOf(gcd));
                newDenominator = newDenominator.divide(BigInteger.valueOf(gcd));
            }
            resultNumerator = resultNumerator.multiply(denominator).add(numerator);
            resultDenominator = resultDenominator.multiply(denominator);
        }
        if (resultDenominator.equals(BigInteger.ONE)) {
            return String.valueOf(resultNumerator);
        } else {
            return resultNumerator + "/" + resultDenominator;
        }
    }
}

