public class Solution {
    public int findMinMoves(int[] machines) {
        int n = machines.length;
        int totalDresses = 0;
        for (int dress : machines) {
            totalDresses += dress;
        }
        if (totalDresses % n != 0) {
            return -1;
        }
        int target = totalDresses / n;
        int minMoves = 0;
        int leftSum = 0;
        for (int i = 0; i < n; i++) {
            leftSum += machines[i];
            int rightSum = totalDresses - leftSum;
            minMoves = Math.max(minMoves, Math.abs(leftSum - target));
            minMoves = Math.max(minMoves, Math.abs(rightSum - target));
        }
        return minMoves;
    }
}

