public class Solution {
    public Node intersect(Node n1, Node n2) {
        if (n1.isLeaf && n2.isLeaf) {
            return new Node(n1.val || n2.val, true);
        }

        if (!n1.isLeaf && !n2.isLeaf) {
            Node topLeft = intersect(n1.topLeft, n2.topLeft);
            Node topRight = intersect(n1.topRight, n2.topRight);
            Node bottomLeft = intersect(n1.bottomLeft, n2.bottomLeft);
            Node bottomRight = intersect(n1.bottomRight, n2.bottomRight);

            if (topLeft.isLeaf && topRight.isLeaf && bottomLeft.isLeaf && bottomRight.isLeaf) {
                return new Node(topLeft.val || topRight.val || bottomLeft.val || bottomRight.val, true);
            } else {
                return new Node(false, false, topLeft, topRight, bottomLeft, bottomRight);
            }
        }

        if (!n1.isLeaf) {
            Node leftTop = intersect(n1.topLeft, n2.topLeft);
            Node leftBottom = intersect(n1.bottomLeft, n2.bottomLeft);
            Node rightTop = intersect(n1.topRight, n2.topRight);
            Node rightBottom = intersect(n1.bottomRight, n2.bottomRight);

            if (leftTop.isLeaf && leftBottom.isLeaf && rightTop.isLeaf && rightBottom.isLeaf) {
                return new Node(leftTop.val || leftBottom.val || rightTop.val || rightBottom.val, true);
            } else {
                return new Node(false, false, leftTop, leftBottom, rightTop, rightBottom);
            }
        }

        if (!n2.isLeaf) {
            Node leftTop = intersect(n1.topLeft, n2.topLeft);
            Node topRight = intersect(n1.topRight, n2.topRight);
            Node bottomLeft = intersect(n1.bottomLeft, n2.bottomLeft);
            Node bottomRight = intersect(n1.bottomRight, n2.bottomRight);

            if (leftTop.isLeaf && topRight.isLeaf && bottomLeft.isLeaf && bottomRight.isLeaf) {
                return new Node(leftTop.val || topRight.val || bottomLeft.val || bottomRight.val, true);
            } else {
                return new Node(false, false, leftTop, topRight, bottomLeft, bottomRight);
            }
        }

        return null;
    }
}

