public class Solution {
    public int findRotateSteps(String ring, String key) {
        int n = ring.length();
        int m = key.length();
        int[][] dp = new int[m][n];

        for (int i = 0; i < m; i++) {
            if (i == 0) {
                for (int j = 0; j < n; j++) {
                    if (ring.charAt(j) == key.charAt(0)) {
                        dp[i][j] = 1 + Math.min(Math.max(j - ring.length() / 2, 0), ring.length() - 1);
                    } else {
                        dp[i][j] = Integer.MAX_VALUE;
                    }
                }
            } else {
                for (int j = 0; j < n; j++) {
                    if (ring.charAt(j) == key.charAt(i)) {
                        int minStep = Integer.MAX_VALUE;
                        for (int k = 0; k < n; k++) {
                            if (Math.abs(k - j) <= i) {
                                minStep = Math.min(minStep, dp[i - 1][k] + Math.min(Math.max(k - ring.length() / 2, 0), ring.length() - 1));
                            }
                        }
                        dp[i][j] = minStep;
                    } else {
                        dp[i][j] = Integer.MAX_VALUE;
                    }
                }
            }
        }

        int minStep = Integer.MAX_VALUE;
        for (int j = 0; j < n; j++) {
            if (ring.charAt(j) == key.charAt(m - 1)) {
                minStep = Math.min(minStep, dp[m - 1][j]);
            }
        }

        return minStep + 1;
    }
}

