public class Solution {
    public String nearestPalindromic(String n) {
        int num = Integer.parseInt(n);
        List<Integer> palindromes = new ArrayList<>();
        for (int i = 1; i <= num / 2; i++) {
            int reversed = reverse(i * 10 + i);
            if (reversed != i * 10 + i) {
                palindromes.add(reversed);
            }
            int reversed2 = reverse(i * 10 + reverse(i));
            if (reversed2 != i * 10 + i && reversed2 < num) {
                palindromes.add(reversed2);
            }
        }
        int minDiff = Integer.MAX_VALUE;
        String result = "";
        for (int palindrome : palindromes) {
            int diff1 = Math.abs(palindrome - num);
            int diff2 = Math.abs(num - palindrome);
            if (diff1 < minDiff || (diff1 == minDiff && diff2 > minDiff)) {
                minDiff = Math.min(diff1, diff2);
                result = String.valueOf(palindrome);
            }
        }
        return result;
    }

    public int reverse(int num) {
        BigInteger bi = new BigInteger(String.valueOf(num));
        return bi.reverse().intValue();
    }
}

