        int[] a = parseComplex(num1);
        int[] b = parseComplex(num2);

        int real = a[0] * b[0] - a[1] * b[1];
        int imaginary = a[0] * b[1] + a[1] * b[0];

        return String.valueOf(real) + "+" + String.valueOf(imaginary) + "i";
