// #2022_07_24_Time_51_ms_(89.62%)_Space_101.7_MB_(47.03%)
import java.util.Comparator;
import java.util.PriorityQueue;

public class Solution {
    public int findMaximizedCapital(int k, int w, int[] profits, int[] capital) {
        int n = profits.length;
        int[][] projects = new int[n][2];
        for (int i = 0; i < n; i++) {
            projects[i] = new int[]{capital[i], profits[i]};
        }

        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (projects[j][0] <= projects[i][0]) {
                    int temp = projects[i][0];
                    projects[i][0] = projects[j][0];
                    projects[j][0] = temp;

                    temp = projects[i][1];
                    projects[i][1] = projects[j][1];
                    projects[j][1] = temp;
                }
            }
        }

        PriorityQueue<int[]> minHeap = new PriorityQueue<>(new Comparator<int[]>() {
            public int compare(int[] a, int[] b) {
                return a[0] - b[0];
            }
        });

        for (int i = 0; i < n; i++) {
            if (projects[i][0] <= w) {
                minHeap.offer(projects[i]);
            } else {
                break;
            }
        }

        int maxCapital = w;
        while (!minHeap.isEmpty() && k > 0) {
            int[] project = minHeap.poll();
            if (maxCapital < project[0]) {
                maxCapital = project[0];
            }
            w += project[1];
            k--;
        }

        return w;
    }
}

