public class Solution {
    public int getMinimumDifference(TreeNode root) {
        int minDiff = Integer.MAX_VALUE;
        TreeNode prevNode = null;

        while (root != null) {
            if (prevNode != null) {
                minDiff = Math.min(minDiff, root.val - prevNode.val);
            }

            if (root.left != null && root.val - root.left.val < minDiff) {
                minDiff = root.val - root.left.val;
            }

            if (root.right != null && root.val - root.right.val < minDiff) {
                minDiff = root.val - root.right.val;
            }

            prevNode = root;

            if (root.left == null && root.right == null) {
                break;
            }

            if (root.left != null) {
                root = root.left;
            } else {
                root = root.right;
            }
        }

        return minDiff;
    }
}

