import java.util.Arrays;

public class Solution {
    public int findUnsortedSubarray(int[] nums) {
        int n = nums.length;
        int start = -1, end = -1;
        for (int i = 0; i < n; i++) {
            if (nums[i] != i + 1) break;
        }
        for (int i = n - 1; i >= 0; i--) {
            if (nums[i] != n - i) break;
        }
        for (int i = nums[0]; i <= nums[n - 1]; i++) {
            int j = Arrays.binarySearch(nums, i);
            if (j < 0) continue;
            for (int k = j; k > 0 && nums[k - 1] > nums[k]; k--) {
                start = Math.max(start, k);
            }
            for (int k = j; k < n && nums[k] > nums[k + 1]; k++) {
                end = Math.min(end, k);
            }
        }
        return end == -1 ? 0 : end - start + 1;
    }
}

