import java.util.*;

public class Solution {
    public boolean checkPerfectNumber(int num) {
        if (num <= 0) return false;

        int sum = 1; // 1 is always a divisor

        for (int i = 2; i * i <= num; i++) {
            int count = 0;
            while (num % i == 0) {
                count++;
                num /= i;
            }

            if (count > 0) {
                sum += (1 + i) * count / 2;
            }
        }

        return num > 0 ? false : true;
    }
}

