        return lengths.size() == 2 && !lengths.contains(0) && Arrays.stream(lengths.toArray()).distinct().count() == 1;
    }

    private int[] getPoint(int i, int[] p1) {
        if (i == 0) {
            return p1;
        } else if (i == 1) {
            return new int[]{p2[0], p2[1]};
        } else if (i == 2) {
            return new int[]{p3[0], p3[1]};
        } else {
            return new int[]{p4[0], p4[1]};
        }
    }

    private int distance(int x1, int y1, int x2, int y2) {
        return (x2 - x1) * (x2 - x1) + (y2 - y1) * (y2 - y1);
    }
}

