import java.util.Arrays;

public class Solution {
    public int findPaths(int m, int n, int maxMove, int startRow, int startColumn) {
        final int MOD = 1000000007;
        int[][] dp = new int[m][n];
        for (int i = 0; i < m; i++) {
            Arrays.fill(dp[i], -1);
        }
        return dfs(m, n, maxMove, startRow, startColumn, dp) % MOD;
    }

    private int dfs(int m, int n, int move, int row, int column, int[][] dp) {
        if (row < 0 || row >= m || column < 0 || column >= n) {
            return 1;
        }
        if (move == 0) {
            return 0;
        }
        if (dp[row][column] != -1) {
            return dp[row][column];
        }
        int res = 0;
        for (int i = -1; i <= 1; i++) {
            for (int j = -1; j <= 1; j++) {
                if (i == 0 && j == 0) continue;
                int newRow = row + i;
                int newColumn = column + j;
                if (newRow >= 0 && newRow < m && newColumn >= 0 && newColumn < n) {
                    res += dfs(m, n, move - 1, newRow, newColumn, dp);
                }
            }
        }
        return dp[row][column] = res % 1000000007;
    }
}

