import java.util.Arrays;
import java.util.ArrayList;
import java.util.List;

public class Solution {
    public int[][] outerTrees(int[][] trees) {
        List<int[]> result = new ArrayList<>();
        Arrays.sort(trees, (a, b) -> Integer.compare(a[0], b[0]));

        for (int i = 0; i < trees.length; i++) {
            while (result.size() >= 2 && crossProduct(result.get(result.size() - 2), result.get(result.size() - 1), trees[i]) <= 0) {
                result.remove(result.size() - 1);
            }
            if (result.size() < 2 || !crossProduct(result.get(result.size() - 2), result.get(result.size() - 1), trees[i]) == 0) {
                result.add(trees[i]);
            }
        }

        List<int[]> hull = new ArrayList<>();
        for (int i = 0; i < result.size(); i++) {
            while (hull.size() >= 2 && crossProduct(hull.get(hull.size() - 2), hull.get(hull.size() - 1), result[i]) <= 0) {
                hull.remove(hull.size() - 1);
            }
            if (hull.size() < 2 || !crossProduct(hull.get(hull.size() - 2), hull.get(hull.size() - 1), result[i]) == 0) {
                hull.add(result[i]);
            }
        }

        int[][] outer = new int[hull.size()][2];
        for (int i = 0; i < hull.size(); i++) {
            outer[i] = hull.get(i);
        }

        return outer;
    }

    private int crossProduct(int[] p1, int[] p2, int[] p3) {
        return (p2[0] - p1[0]) * (p3[1] - p2[1]) - (p2[1] - p1[1]) * (p3[0] - p2[0]);
    }
}

