public class Solution {
    public int numSubmat(int[][] mat) {
        int m = mat.length;
        if (m == 0) return 0;

        int n = mat[0].length;
        int[] height = new int[n];
        int total = 0;

        for (int i = 0; i < m; i++) {
            int[] left = new int[n];
            Arrays.fill(left, 0);
            int[] right = new int[n];
            Arrays.fill(right, n - 1);

            for (int j = 0; j < n; j++) {
                if (mat[i][j] == 1) {
                    height[j]++;
                    left[j] = Math.max(left[j], j);
                    right[j] = Math.min(right[j], j);
                } else {
                    height[j] = 0;
                }
            }

            for (int j = 0; j < n; j++) {
                total += height[j] * Math.min(left[j], right[j]);
            }
        }

        return total;
    }
}

