public class Solution {
    public int minInsertions(String s) {
        Stack<Character> stack = new Stack<>();
        int insertions = 0;

        for (char c : s.toCharArray()) {
            if (c == '(') {
                stack.push(c);
            } else {
                if (!stack.isEmpty() && stack.peek() == '(') {
                    stack.pop();
                } else {
                    insertions += 2; // (( or )
                }
            }
        }

        insertions += stack.size() * 2; // remaining ( and )

        return insertions;
    }
}

