import java.util.*;

public class Solution {
    public int minOperationsMaxProfit(int[] customers, int boardingCost, int runningCost) {
        int n = customers.length;
        int maxProfit = 0;
        int maxRotations = 0;
        int currentProfit = 0;
        int rotations = 0;
        int waiting = 0;

        for (int i = 0; i < n || waiting > 0; ) {
            if (i < n) {
                waiting += customers[i];
                i++;
            }
            int board = Math.min(waiting, 4);
            currentProfit += boardingCost * board - runningCost;
            waiting -= board;
            rotations++;

            while (waiting >= 4) {
                waiting -= 4;
                currentProfit += boardingCost * 4 - runningCost;
                rotations++;
            }
        }

        for (int i = 0; i < n && waiting > 0; ) {
            int board = Math.min(waiting, 4);
            currentProfit += boardingCost * board - runningCost;
            waiting -= board;
            rotations++;
        }

        while (waiting > 0) {
            currentProfit += boardingCost * waiting - runningCost;
            waiting = 0;
            rotations++;
        }

        for (int i = maxRotations; i < rotations; i++) {
            currentProfit -= runningCost;
        }

        return Math.max(0, currentProfit);
    }
}

