import java.util.Arrays;
import java.util.List;

public class Solution {
    public int connectTwoGroups(List<List<Integer>> cost) {
        int size1 = cost.size();
        int size2 = cost.get(0).size();

        // Initialize dp array with infinity
        int[] dp = new int[1 << size2];
        Arrays.fill(dp, Integer.MAX_VALUE);

        // Base case: connecting the first node in set 2
        dp[0] = 0;

        for (int mask = 0; mask < (1 << size2); mask++) {
            for (int i = 0; i < size1; i++) {
                int nextMask = mask | (1 << ((cost.get(i).size() - 1) - (mask >> Integer.bitCount(mask))));
                if (dp[mask] != Integer.MAX_VALUE && dp[mask] + cost.get(i).get((cost.get(i).size() - 1) - (mask >> Integer.bitCount(mask))) < dp[nextMask]) {
                    dp[nextMask] = dp[mask] + cost.get(i).get((cost.get(i).size() - 1) - (mask >> Integer.bitCount(mask)));
                }
            }
        }

        return dp[(1 << size2) - 1];
    }
}

