import java.util.Arrays;

public class Solution {
    public int minSwaps(int[][] grid) {
        int n = grid.length;
        int[] rowCounts = new int[n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    rowCounts[j]++;
                }
            }
        }

        Arrays.sort(rowCounts);
        int onesAboveDiagonal = 0;
        for (int i = 0; i < n / 2; i++) {
            onesAboveDiagonal += rowCounts[i];
        }

        if (onesAboveDiagonal > (n - 1) * (n + 1) / 2) {
            return 1;
        }

        int swaps = 0;
        for (int i = n - 1; i >= 0; i--) {
            while (rowCounts[i] > 0 && rowCounts[i] < i + 1) {
                rowCounts[i]--;
                swaps++;
            }
        }

        return swaps;
    }
}

