public class Solution {
    public int countPairs(TreeNode root, int distance) {
        return dfs(root, null, 0, distance);
    }

    private int dfs(TreeNode node, TreeNode parent, int depth, int distance) {
        if (node == null) {
            return 0;
        }
        if (parent != null && node.val == parent.val + 1) {
            return 0;
        }
        if (node.left == null && node.right == null) {
            int res = 0;
            for (int i = 1; i <= distance; i++) {
                res += dfs(root, node, depth + i, distance);
            }
            return res;
        }
        return dfs(node.left, node, depth + 1, distance) + dfs(node.right, node, depth + 1, distance);
    }
}

