public class Solution {
    public String reorderSpaces(String text) {
        int totalSpaces = 0;
        int wordCount = 0;

        for (int i = 0; i < text.length(); i++) {
            if (!Character.isLetter(text.charAt(i))) {
                totalSpaces++;
            } else {
                wordCount++;
            }
        }

        if (wordCount == 1) {
            return text + new String(new char[totalSpaces]).replace("\0", " ") + "\n";
        }

        int spacesBetweenWords = totalSpaces / (wordCount - 1);
        int remainingSpaces = totalSpaces % (wordCount - 1);

        StringBuilder result = new StringBuilder();
        int spaceCount = 0;
        for (int i = 0; i < text.length(); i++) {
            if (!Character.isLetter(text.charAt(i))) {
                if (++spaceCount <= wordCount) {
                    for (int j = 0; j <= spacesBetweenWords; j++) {
                        result.append(" ");
                    }
                    if (remainingSpaces > 0) {
                        --remainingSpaces;
                        result.append(" ");
                    }
                } else {
                    result.append(text.charAt(i));
                }
            } else {
                result.append(text.charAt(i));
            }
        }

        return result.toString();
    }
}

