            sum += nums[i];
            if (sum == target) {
                sumIndexMap.put(i, i);
            }
        }

        int maxCount = 0;
        int prevEnd = -1;
        for (int i = 0; i < nums.length; i++) {
            if (i > prevEnd && sumIndexMap.containsKey(i)) {
