public class Solution {
    public double maxProbability(int n, int[][] edges, double[] succProb, int start, int end) {
        List<List<int[]>> graph = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }
        for (int i = 0; i < edges.length; i++) {
            graph.get(edges[i][0]).add(new int[]{edges[i][1], (int) (succProb[i] * 1000000)});
            graph.get(edges[i][1]).add(new int[]{edges[i][0], (int) (succProb[i] * 1000000)});
        }

        double[] prob = new double[n];
        Arrays.fill(prob, 0);
        prob[start] = 1;

        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> b[1] - a[1]);
        pq.offer(new int[]{start, 1});

        while (!pq.isEmpty()) {
            int[] node = pq.poll();
            if (node[0] == end) return node[1] / 1000000.0;

            for (int[] neighbor : graph.get(node[0])) {
                if (neighbor[1] > prob[neighbor[0]]) {
                    prob[neighbor[0]] = neighbor[1];
                    pq.offer(new int[]{neighbor[0], neighbor[1]});
                }
            }
        }

        return 0;
    }
}

