import java.util.HashSet;
import java.util.Set;

public class Solution {
    public boolean isPrintable(int[][] targetGrid) {
        int m = targetGrid.length, n = targetGrid[0].length;
        Set<Integer> printedColors = new HashSet<>();

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                int color = targetGrid[i][j];
                if (!printedColors.contains(color)) {
                    boolean[] visited = new boolean[m * n];
                    dfs(targetGrid, printedColors, visited, color, i, j);
                }
            }
        }

        return printedColors.size() == m * n;
    }

    private void dfs(int[][] targetGrid, Set<Integer> printedColors, boolean[] visited, int color, int i, int j) {
        if (visited[i * targetGrid[0].length + j]) {
            return;
        }
        visited[i * targetGrid[0].length + j] = true;

        for (int k = 0; k < targetGrid.length; k++) {
            for (int l = 0; l < targetGrid[0].length; l++) {
                if (targetGrid[k][l] == color) {
                    int minI = Math.max(0, i - k);
                    int maxI = Math.min(targetGrid.length - 1, i + k);
                    int minJ = Math.max(0, j - l);
                    int maxJ = Math.min(targetGrid[0].length - 1, j + l);

                    for (int x = minI; x <= maxI; x++) {
                        for (int y = minJ; y <= maxJ; y++) {
                            if (!visited[x * targetGrid[0].length + y] && targetGrid[x][y] == color) {
                                return;
                            }
                        }
                    }
                }
            }
        }

        printedColors.add(color);
    }
}

