public class Solution {
    public int diagonalSum(int[][] mat) {
        int sum = 0;
        int n = mat.length;

        // Sum of primary diagonal
        for (int i = 0; i < n; i++) {
            sum += mat[i][i];
        }

        // Sum of secondary diagonal
        for (int i = 0; i < n; i++) {
            sum += mat[i][n - i - 1];
        }

        // If the matrix is not a square, subtract the middle element if it's an odd number
        if (n % 2 != 0) {
            sum -= mat[n / 2][n / 2];
        }

        return sum;
    }
}

