import java.math.BigInteger;
import java.util.Tuple;

public class Solution {
    public Tuple<Long, Long> maxProduct(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        long[][] dp1 = new long[m][n];
        long[][] dp2 = new long[m][n];

        dp1[0][0] = 1;
        dp2[0][0] = 1;

        for (int i = 1; i < m; i++) {
            dp1[i][0] = Math.max(1, dp1[i - 1][0]) * grid[i][0];
            dp2[i][0] = Math.min(1, dp2[i - 1][0]) * grid[i][0];
        }

        for (int j = 1; j < n; j++) {
            dp1[0][j] = Math.max(1, dp1[0][j - 1]) * grid[0][j];
            dp2[0][j] = Math.min(1, dp2[0][j - 1]) * grid[0][j];
        }

        for (int i = 1; i < m; i++) {
            for (int j = 1; j < n; j++) {
                dp1[i][j] = Math.max(Math.max(dp1[i - 1][j], dp2[i - 1][j]), Math.max(dp1[i][j - 1], dp2[i][j - 1])) * grid[i][j];
                dp2[i][j] = Math.min(Math.min(dp1[i - 1][j], dp2[i - 1][j]), Math.min(dp1[i][j - 1], dp2[i][j - 1])) * grid[i][j];
            }
        }

        long maxProduct = dp1[m - 1][n - 1];
        BigInteger result = new BigInteger(String.valueOf(maxProduct));
        result = result.mod(new BigInteger("1000000007"));

        return new Tuple<>(result.longValue(), 0);
    }
}

