import java.util.*;

public class Solution {
    public boolean containsCycle(char[][] grid) {
        int m = grid.length;
        if (m == 0) return false;
        int n = grid[0].length;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] != '\0') {
                    boolean[] visited = new boolean[m * n];
                    if (hasCycle(grid, i, j, visited)) return true;
                }
            }
        }

        return false;
    }

    private boolean hasCycle(char[][] grid, int x, int y, boolean[] visited) {
        int m = grid.length;
        int n = grid[0].length;
        int dx[] = {-1, 1, 0, 0};
        int dy[] = {0, 0, -1, 1};

        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{x, y});
        visited[x * n + y] = true;

        while (!queue.isEmpty()) {
            int[] p = queue.poll();
            x = p[0];
            y = p[1];

            for (int i = 0; i < 4; i++) {
                int nx = x + dx[i];
                int ny = y + dy[i];

                if (nx >= 0 && nx < m && ny >= 0 && ny < n) {
                    if (grid[nx][ny] == grid[x][y] && !visited[nx * n + ny]) {
                        visited[nx * n + ny] = true;
                        queue.offer(new int[]{nx, ny});
                    }
                }
            }
        }

        for (int i = 0; i < m * n; i++) {
            if (!visited[i]) return false;
        }

        return true;
    }
}

