                    if (right < 0) right = -right - 1;
                    for (int k = Math.max(left, right); k >= 0; k--) {
                        dp[i][j] += dp[k][Math.min(j, locations[i] - locations[k])];
                        dp[i][j] %= MOD;
                    }
                }
            }
        }
        return dp[n - 1][fuel];
    }
}

