import java.util.Arrays;

public class Solution {
    public int maxSum(int[] nums1, int[] nums2) {
        int n = nums1.length;
        int m = nums2.length;
        int[][] dp = new int[n + 1][m + 1];
        for (int i = 0; i <= n; i++) {
            Arrays.fill(dp[i], Integer.MIN_VALUE);
        }
        for (int i = 0; i < n; i++) {
            if (nums1[i] == nums2[0]) {
                dp[i][0] = nums1[i];
            } else {
                dp[i][0] = Math.max(nums1[i], dp[i - 1][0]);
            }
        }
        for (int j = 0; j < m; j++) {
            if (nums2[j] == nums1[0]) {
                dp[0][j] = nums2[j];
            } else {
                dp[0][j] = Math.max(nums2[j], dp[0][j - 1]);
            }
        }
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (nums1[i - 1] == nums2[j - 1]) {
                    dp[i][j] = Math.max(dp[i - 1][j - 1] + nums1[i - 1], Math.max(dp[i - 1][j], dp[i][j - 1]));
                } else if (nums1[i - 1] < nums2[j - 1]) {
                    dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
                } else {
                    dp[i][j] = Math.max(dp[i][j - 1], dp[i - 1][j]);
                }
            }
        }
        return dp[n][m] % (1000000007);
    }
}

