public class Solution {
    public int maxSumRangeQuery(int[] nums, int[][] requests) {
        int n = nums.length;
        int[] tempArr = new int[n];

        for (int[] request : requests) {
            tempArr[request[0]]++;
            if (request[1] + 1 < n) {
                tempArr[request[1] + 1]--;
            }
        }

        IntStream.range(0, n).forEach(i -> nums[i] += tempArr[i]);

        Arrays.sort(nums);
        int[] res = new int[n];
        for (int i = 0; i < n; i++) {
            res[i] = n - i - 1;
        }
        Arrays.sort(res);

        return IntStream.range(0, n).map(i -> nums[i] * res[n - i - 1]).sum() % (1000000007);
    }
}

