public class Solution {
    public List<String> highAccessEmployees(String[][] accesstimes) {
        Map<String, Integer> employeeAccessCount = new HashMap<>();
        for (String[] time : accesstimes) {
            String employeeName = time[0];
            int accessTime = Integer.parseInt(time[1].substring(0, 2)) * 60 + Integer.parseInt(time[1].substring(2));
            if (!employeeAccessCount.containsKey(employeeName)) {
                employeeAccessCount.put(employeeName, new ArrayList<>());
            }
            employeeAccessCount.get(employeeName).add(accessTime);
        }

        List<String> highAccessEmployees = new ArrayList<>();
        for (Map.Entry<String, List<Integer>> entry : employeeAccessCount.entrySet()) {
            String employeeName = entry.getKey();
            List<Integer> accessTimes = entry.getValue();
            Collections.sort(accessTimes);

            int start = accessTimes.get(0);
            int end = accessTimes.get(accessTimes.size() - 1);
            for (int i = 1; i < accessTimes.size(); i++) {
                if (accessTimes.get(i) - accessTimes.get(i - 1) >= 60) {
                    start = accessTimes.get(i);
                    break;
                }
            }

            for (int i = accessTimes.size() - 2; i > 0; i--) {
                if (accessTimes.get(i) - accessTimes.get(i - 1) >= 60) {
                    end = accessTimes.get(i);
                    break;
                }
            }

            int count = 0;
            for (int time : accessTimes) {
                if (time >= start && time <= end) {
                    count++;
                } else if (time < start || time > end) {
                    start = time;
                    end = time;
                    count = 1;
                }
            }

            if (count >= 3) {
                highAccessEmployees.add(employeeName);
            }
        }

        return highAccessEmployees;
    }
}

