public class Solution {
    public int maximumLength(String s) {
        Map<Character, Integer> map = new HashMap<>();
        int maxLen = -1;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (!map.containsKey(c)) {
                map.put(c, i);
            } else {
                int len = i - map.get(c) + 1;
                while (len >= 3 && !isSpecial(s.substring(map.get(c), i + 1))) {
                    map.remove(c);
                    c = s.charAt(i);
                    if (!map.containsKey(c)) {
                        map.put(c, i);
                    } else {
                        len = i - map.get(c) + 1;
                    }
                }
                maxLen = Math.max(maxLen, len);
            }
        }
        return maxLen;
    }

    private boolean isSpecial(String s) {
        return new String(new char[] {s.charAt(0)}).equals(s);
    }
}

