import java.util.*;

public class Solution {
    public int minCost(String source, String target, char[] original, char[] changed, int[][] cost) {
        int n = source.length();
        int[][] dp = new int[n][n];

        for (int i = 0; i < n; i++) {
            if (source.charAt(i) == target.charAt(i)) {
                dp[i][i] = 0;
            } else {
                int minCost = Integer.MAX_VALUE;
                for (int j = 0; j < n; j++) {
                    if (original[j] == source.charAt(i) && changed[j] == target.charAt(i)) {
                        minCost = Math.min(minCost, cost[j][i]);
                    }
                }
                dp[i][i] = minCost;
            }
        }

        for (int length = 2; length <= n; length++) {
            for (int i = 0; i < n - length + 1; i++) {
                int j = i + length - 1;
                if (source.charAt(i) == target.charAt(i) && source.charAt(j) == target.charAt(j)) {
                    dp[i][j] = dp[i+1][j-1];
                } else {
                    int minCost = Integer.MAX_VALUE;
                    for (int k = i; k <= j; k++) {
                        if (source.charAt(k) != target.charAt(k)) {
                            minCost = Math.min(minCost, dp[i][k-1] + dp[k+1][j] + cost[Arrays.asList(original).indexOf(source.charAt(k))][Arrays.asList(changed).indexOf(target.charAt(k))]);
                        }
                    }
                    dp[i][j] = minCost;
                }
            }
        }

        return dp[0][n-1];
    }
}

