        Stack<Integer> stack = new Stack<>();
        int maxLen = 0;

        for (int num : nums) {
            while (!stack.isEmpty() && stack.peek() > num) {
                int top = stack.pop();
                int len = stack.isEmpty() ? 0 : stack.peek() - top + 1;
                maxLen = Math.max(maxLen, len);
