import java.util.*;

public class Solution {
    public int maximumStrongPairXor(int[] nums) {
        TrieNode root = new TrieNode();
        for (int num : nums) {
            int xor = 0;
            for (int i = 31; i >= 0; i--) {
                int bit = ((num >> i) & 1);
                if (!root.children[bit].exist) {
                    root.children[bit] = new TrieNode();
                }
                xor |= bit;
                root = root.children[bit];
            }
            root.exist = true;
        }
        int maxXor = 0;
        for (int num : nums) {
            int xor = 0;
            for (int i = 31; i >= 0; i--) {
                int bit = ((num >> i) & 1);
                TrieNode node = root.children[1 - bit];
                while (node != null) {
                    if (!node.exist) {
                        break;
                    }
                    xor |= bit;
                    node = node.children[bit];
                }
            }
            maxXor = Math.max(maxXor, num ^ xor);
        }
        return maxXor;
    }

    class TrieNode {
        int[] children = new int[2];
        boolean exist;

        public TrieNode() {
            for (int i = 0; i < 2; i++) {
                children[i] = -1;
            }
            exist = false;
        }
    }
}

