                char c = s.charAt(j);
                if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u') {
                    vowels++;
                } else {
                    consonants++;
                }
                if ((vowels * consonants) % k != 0) {
                    break;
                }
            }
            count += j - i + 1;
        }
        return count;
    }
}

