import java.util.ArrayList;
import java.util.List;

public class Solution {
    public long[] placedCoins(int[][] edges, int[] cost) {
        List<Integer>[] graph = (List<Integer>[]) new List[edges.length];
        for (int i = 0; i < edges.length; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int i = 0; i < edges.length; i++) {
            int a = edges[i][0], b = edges[i][1];
            graph[a].add(b);
            graph[b].add(a);
        }

        long[] res = new long[cost.length];
        dfs(graph, cost, -1, res);

        return res;
    }

    private void dfs(List<Integer>[] graph, int[] cost, int node, long[] res) {
        if (node == -1) {
            for (int i = 0; i < cost.length; i++) {
                res[i] = placeCoins(graph, cost, i);
            }
            return;
        }

        for (int neighbor : graph[node]) {
            dfs(graph, cost, neighbor, res);
        }
    }

    private long placeCoins(List<Integer>[] graph, int[] cost, int node) {
        if (graph[node].size() < 3) {
            return 1L;
        } else {
            PriorityQueue<Long> pq = new PriorityQueue<>(Comparator.reverseOrder());
            for (int neighbor : graph[node]) {
                for (int grandchild : graph[neighbor]) {
                    if (grandchild != node) {
                        pq.add((long) cost[grandchild]);
                    }
                }
                while (pq.size() > 3) {
                    pq.poll();
                }
                long product = 1L;
                for (int i = 0; i < 3 && !pq.isEmpty(); i++) {
                    product *= pq.poll();
                }
                return Math.max(product, 0L);
            }
        }
    }
}

