                } else {
                    for (int k = j; k < i; k++) {
                        int temp = Math.min(dp[j][k], dp[k + 1][i - 1]);
                        if (temp != Integer.MAX_VALUE) {
                            dp[i][j] = Math.min(dp[i][j], temp + map.getOrDefault(source.substring(j, i), Integer.MAX_VALUE));
