                for (Map.Entry<Character, Integer> entry : map1.entrySet()) {
                    if (!map2.containsKey(entry.getKey())) {
                        canMake = false;
                        break;
                    } else if (entry.getValue() != map2.get(entry.getKey())) {
                        canMake = false;
