    public int findKOr(int[] nums, int k) {
        Arrays.sort(nums);
        int res = 0;
        for (int i = 31; i >= 0; i--) {
            int count = 0;
            while (i <= 31 && (count < k || (count == k && (res & (1 << i)) == 0))) {
                if (i > 0) {
                    while (i > 0 && (nums[0] & (1 << i)) == 0) {
                        nums = Arrays.copyOfRange(Arrays.copyOfRange(nums, 1, nums.length), 0, nums.length - 1);
                    }
                } else {
                    if (count < k) {
                        break;
                    }
                }
                count += Integer.bitCount(nums[0]);
                res |= nums[0] << i;
            }
        }
        return res;
    }
}

