import java.util.Arrays;

public class Solution {
    public int[][] constructProductMatrix(int[][] grid) {
        int n = grid.length;
        int m = grid[0].length;

        // Calculate prefix product for each row
        int[][] prefixProductRow = new int[n][m];
        for (int i = 0; i < n; i++) {
            int prefixProduct = 1;
            for (int j = 0; j < m; j++) {
                prefixProduct *= grid[i][j];
                prefixProduct %= 1000000007;
                prefixProductRow[i][j] = prefixProduct;
            }
        }

        // Calculate suffix product for each column
        int[][] suffixProductCol = new int[n][m];
        for (int j = 0; j < m; j++) {
            int suffixProduct = 1;
            for (int i = 0; i < n; i++) {
                suffixProduct *= grid[i][j];
                suffixProduct %= 1000000007;
                suffixProductCol[i][j] = suffixProduct;
            }
        }

        // Calculate product matrix
        int[][] productMatrix = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                productMatrix[i][j] = prefixProductRow[i][j] * suffixProductCol[i][j];
                productMatrix[i][j] %= 1000000007;
            }
        }

        return productMatrix;
    }
}

