import java.util.Map;

public class Solution {
    public int maxFrequencyScore(int[] nums, long k) {
        Arrays.sort(nums);
        int n = nums.length;
        int res = 0;
        for (int i = 0; i < n; i++) {
            int left = i, right = n - 1;
            while (left <= right) {
                int mid = left + (right - left) / 2;
                if (nums[mid] * (mid - i + 1) > k) {
                    right = mid - 1;
                } else {
                    long cost = (long) nums[mid] * (mid - i + 1);
                    int j = mid;
                    while (j < n && nums[j] == nums[mid]) {
                        j++;
                    }
                    if ((j - mid) * cost <= k) {
                        res = Math.max(res, nums[mid]);
                        left = j;
                    } else {
                        right = mid - 1;
                    }
                }
            }
        }
        return res;
    }
}

