        Arrays.sort(hFences);
        Arrays.sort(vFences);

        int maxArea = -1;

        for (int i = 0; i < hFences.length - 1; i++) {
            for (int j = i + 1; j < hFences.length; j++) {
                int minH = Math.min(hFences[i], hFences[j]);
                int maxH = Math.max(hFences[i], hFences[j]);

                for (int k = 0; k < vFences.length - 1; k++) {
                    for (int l = k + 1; l < vFences.length; l++) {
                        int minV = Math.min(vFences[k], vFences[l]);
                        int maxV = Math.max(vFences[k], vFences[l]);

                        if (minH >= maxV && maxH <= minV) {
                            int area = (maxH - minH) * (maxV - minV);
                            maxArea = Math.max(maxArea, area % 1000000007);
                        }
                    }
                }
            }
        }

        return maxArea;
    }
}

