import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int minimumOperationsToMakeEqual(int x, int y) {
        Map<Integer, Integer> memo = new HashMap<>();

        return dfs(x, y, 0, memo);
    }

    private int dfs(int x, int y, int ops, Map<Integer, Integer> memo) {
        if (x == y) {
            return ops;
        }

        if (memo.containsKey(x)) {
            return memo.get(x);
        }

        int res = Integer.MAX_VALUE;

        if (x % 11 == 0) {
            res = Math.min(res, dfs(x / 11, y, ops + 1, memo));
        }

        if (x % 5 == 0) {
            res = Math.min(res, dfs(x / 5, y, ops + 1, memo));
        }

        if (x > y) {
            res = Math.min(res, dfs(x - 1, y, ops + 1, memo));
        } else if (y > x) {
            res = Math.min(res, dfs(x, y - 1, ops + 1, memo));
        }

        memo.put(x, res);
        return res;
    }
}

