import java.util.ArrayList;
import java.util.List;

public class Solution {
    public int maxPoints(int n, int[][] edges, int[] coins, int k) {
        List<Integer>[] graph = new List[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] edge : edges) {
            graph[edge[0]].add(edge[1]);
            graph[edge[1]].add(edge[0]);
        }

        int[] dp = new int[n];
        boolean[] visited = new boolean[n];

        dfs(graph, 0, -1, coins, k, dp, visited);

        return maxPoints(dp);
    }

    private void dfs(List<Integer>[] graph, int node, int parent, int[] coins, int k, int[] dp, boolean[] visited) {
        if (visited[node]) {
            return;
        }
        visited[node] = true;

        int points = 0;
        for (int neighbor : graph[node]) {
            if (neighbor != parent) {
                dfs(graph, neighbor, node, coins, k, dp, visited);
                points += Math.max(dp[neighbor], 0);
            }
        }

        int collectAll = coins[node] - k;
        if (collectAll > 0) {
            points += collectAll;
        } else {
            points -= Math.abs(collectAll);
        }

        int halfCollect = coins[node] / 2;
        if (halfCollect > 0) {
            for (int neighbor : graph[node]) {
                dp[neighbor] /= 2;
            }
            points += halfCollect;
        }

        dp[node] = points;
    }

    private int maxPoints(int[] dp) {
        int maxPoints = Integer.MIN_VALUE;
        for (int point : dp) {
            maxPoints = Math.max(maxPoints, point);
        }
        return maxPoints;
    }
}

