import java.util.PriorityQueue;

public class Solution {
    public int minOperations(int[] nums, int k) {
        PriorityQueue<Integer> pq = new PriorityQueue<>();
        for (int num : nums) {
            pq.offer(num);
        }

        int operations = 0;
        while (!pq.isEmpty()) {
            int x = pq.poll();
            if (x < k) {
                int y = pq.poll();
                int add = Math.min(x, y) * 2 + Math.max(x, y);
                pq.clear();
                for (int num : nums) {
                    if (num >= k) {
                        pq.offer(num - add);
                    }
                }
                operations++;
            } else {
                break;
            }
        }

        return operations;
    }
}

