import java.util.HashMap;
import java.util.Map;

public class Solution {
    public long countPrefixSuffixPairs(String[] words) {
        Map<String, Long> prefixCount = new HashMap<>();
        Map<String, Long> suffixCount = new HashMap<>();

        long count = 0;
        for (String word : words) {
            String prefix = word.substring(0);
            String suffix = new StringBuilder(word).reverse().toString();
            if (!prefixCount.containsKey(prefix)) {
                prefixCount.put(prefix, 1L);
            } else {
                prefixCount.put(prefix, prefixCount.get(prefix) + 1L);
            }
            if (!suffixCount.containsKey(suffix)) {
                suffixCount.put(suffix, 1L);
            } else {
                suffixCount.put(suffix, suffixCount.get(suffix) + 1L);
            }
        }

        for (Map.Entry<String, Long> entry : prefixCount.entrySet()) {
            long countForPrefix = entry.getValue();
            if (suffixCount.containsKey(entry.getKey())) {
                count += countForPrefix * suffixCount.get(entry.getKey());
            } else {
                for (Map.Entry<String, Long> suffixEntry : suffixCount.entrySet()) {
                    if (entry.getKey().equals(suffixEntry.getKey().substring(0))) {
                        count += countForPrefix * suffixEntry.getValue();
                    }
                }
            }
        }

        return count;
    }
}

