public class Solution {
    public int countPrefixSuffixPairs(String[] words) {
        Map<String, Integer> map = new HashMap<>();
        int count = 0;

        for (int i = 0; i < words.length; i++) {
            for (int j = i + 1; j < words.length; j++) {
