public class Solution {
    public int minimumSubarrayLength(int[] nums, int k) {
        int n = nums.length;
        if (n == 0) return -1;

        int res = Integer.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            int or = 0;
            for (int j = i; j < n; j++) {
                or |= nums[j];
                if ((or >= k) && (j - i + 1) < res) {
                    res = j - i + 1;
                }
            }
        }

        return res == Integer.MAX_VALUE ? -1 : res;
    }
}

