public class Solution {
    public int minOperations(int k) {
        int operations = 0;
        int[] nums = new int[1];
        nums[0] = 1;

        while (Arrays.stream(nums).sum() < k) {
            int maxNum = Arrays.stream(nums).max().getAsInt();
            if (maxNum * 2 >= k) {
                operations += maxNum - (k - maxNum);
                break;
            }
            nums = Arrays.copyOf(nums, nums.length + 1);
            nums[nums.length - 1] = maxNum * 2;
            operations++;
        }

        return operations;
    }
}

