public class Solution {
    public int mostFrequentPrime(int[][] mat) {
        Map<Integer, Integer> primeCount = new HashMap<>();
        for (int i = 0; i < mat.length; i++) {
            for (int j = 0; j < mat[0].length; j++) {
                StringBuilder num = new StringBuilder();
                int direction = 1;
                while (i + direction >= 0 && i + direction < mat.length && j + direction >= 0 && j + direction < mat[0].length) {
                    num.append(mat[i + direction][j + direction]);
                    if (direction == 1) {
                        direction = 8; // east
                    } else if ((direction & 1) == 0) {
                        direction >>= 1; // south, west
                    } else {
                        direction &= ~3; // north-east, south-west
                    }
                }
                int n = Integer.parseInt(num.toString());
                boolean isPrime = true;
                for (int p = 2; p * p <= n; p++) {
                    if (n % p == 0) {
                        isPrime = false;
                        break;
                    }
                }
                if (isPrime && n > 10) {
                    primeCount.put(n, primeCount.getOrDefault(n, 0) + 1);
                }
            }
        }
        int maxCount = 0;
        int mostFrequentPrime = -1;
        for (Map.Entry<Integer, Integer> entry : primeCount.entrySet()) {
            if (entry.getValue() > maxCount) {
                maxCount = entry.getValue();
                mostFrequentPrime = entry.getKey();
            } else if (entry.getValue() == maxCount) {
                mostFrequentPrime = Math.max(mostFrequentPrime, entry.getKey());
            }
        }
        return mostFrequentPrime;
    }
}

