public class Solution {
    public int countSubmatrices(int[][] grid, int k) {
        int m = grid.length;
        int n = grid[0].length;
        int res = 0;

        for (int i = 0; i < m; i++) {
            int[] prefixSum = new int[n];
            Arrays.fill(prefixSum, 0);

            for (int j = i; j < m; j++) {
                for (int col = 0; col < n; col++) {
                    prefixSum[col] += grid[j][col];
                }

                for (int left = 0; left < n; left++) {
                    int right = n - 1;
                    while (right > left) {
                        if (prefixSum[left] + prefixSum[right] <= k) {
                            res += n - 1 - right;
                        }
                        right--;
                    }
                }
            }
        }

        return res;
    }
}

