public class Solution {
    public int[][] resultGrid(int[][] image, int threshold) {
        int m = image.length;
        int n = image[0].length;
        int[][] result = new int[m][n];

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                Set<Integer> regionSet = new HashSet<>();
                dfs(image, i, j, threshold, regionSet);
                List<Integer> intensityList = new ArrayList<>();
                for (int k : regionSet) {
                    intensityList.add(k);
                }
                int averageIntensity = 0;
                if (!intensityList.isEmpty()) {
                    averageIntensity = (int) Math.floor((double) Collections.min(intensityList) + 
                            (Collections.max(intensityList) - Collections.min(intensityList)) / (intensityList.size() - 1));
                }
                result[i][j] = averageIntensity;
            }
        }

        return result;
    }

    private void dfs(int[][] image, int i, int j, int threshold, Set<Integer> regionSet) {
        if (i < 0 || i >= image.length || j < 0 || j >= image[0].length) {
            return;
        }
        if (image[i][j] > threshold) {
            return;
        }

        for (int x = -1; x <= 1; x++) {
            for (int y = -1; y <= 1; y++) {
                int newX = i + x;
                int newY = j + y;
                if (newX >= 0 && newX < image.length && newY >= 0 && newY < image[0].length) {
                    if (Math.abs(image[newX][newY] - image[i][j]) <= threshold) {
                        regionSet.add(image[newX][newY]);
                        dfs(image, newX, newY, threshold, regionSet);
                    }
                }
            }
        }
    }
}

