        for (int i = 0; i < n; i++) {
            count[i] = dfs(graph, i, signalSpeed);
        }
        return count;
    }

    private int dfs(List<List<Integer>> graph, int node, int signalSpeed) {
        boolean[] visited = new boolean[graph.size()];
        int count = 0;
        for (int neighbor : graph.get(node)) {
            if (!visited[neighbor]) {
                visited[neighbor] = true;
                if ((node < neighbor && dfs(graph, neighbor, signalSpeed) % signalSpeed == 0) ||
                        (node > neighbor && dfs(graph, neighbor, signalSpeed) % signalSpeed == 0)) {
                    count++;
                }
            }
        }
        return count;
    }
}

