public class Solution {
    public long minimumMoves(int[] nums, int k, int maxChanges) {
        int n = nums.length;
        int ones = 0;
        for (int num : nums) {
            if (num == 1) {
                ones++;
            }
        }

        if (k > ones) {
            return -1;
        }

        long ans = Long.MAX_VALUE;
        for (int i = 0; i <= n - k; i++) {
            int leftOnes = 0;
            for (int j = i; j < i + k; j++) {
                if (nums[j] == 1) {
                    leftOnes++;
                }
            }

            long moves = (long) Math.min(leftOnes, k - leftOnes);
            moves += (long) Math.min(Math.max(0, leftOnes - maxChanges), k - leftOnes);

            ans = Math.min(ans, moves);
        }

        return ans;
    }
}

