public class Solution {
    public long[] countOfPairs(int n, int x, int y) {
        long[] result = new long[n];
        Arrays.fill(result, 0);

        for (int i = 1; i <= n - 1; i++) {
            if (x > i && y > i) {
                result[i] += i;
            } else if (x < i && y < i) {
                result[n - i] += i;
            } else if ((x > i && y < i) || (x < i && y > i)) {
                result[Math.min(x, y)] += i;
                result[Math.max(x, y)] += i;
            }
        }

        for (int i = 1; i <= n - 1; i++) {
            if (x > i && y > i) {
                result[i] += result[n - i];
            } else if (x < i && y < i) {
                result[n - i] += result[i];
            }
        }

        return result;
    }
}

