        int res = Integer.MAX_VALUE;
        for (int i = 0; i < nums.length; i++) {
            int or = 0;
            for (int j = i; j < nums.length; j++) {
                or |= nums[j];
                if ((or >= k) && (j - i + 1 < res)) {
