        int n = nums.length;
        long[][] dp = new long[n + 1][k + 1];
        Arrays.fill(dp[0], (long) -1e9);

        for (int i = 1; i <= n; i++) {
            for (int j = Math.min(i, k); j >= 1; j--) {
