public class Solution {
    public int subsequenceSum(int[] nums, int k) {
        long res = 0;
        Arrays.sort(nums);
        Map<Long, Long> map = new HashMap<>();
        map.put(0L, 1L);
        for (int i = 0; i < nums.length - k + 1; i++) {
            long cur = nums[i];
            for (long j = map.lastKey() + 1; ; j++) {
                if (!map.containsKey(j)) break;
