import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int minimumTimeToInitialState(String w, int q) {
        Map<Character, Integer> map = new HashMap<>();
        for (int i = 0; i < w.length(); i++) {
            char c = w.charAt(i);
            map.put(c, map.getOrDefault(c, 0) + 1);
        }

        int time = 0;
        while (!isInitialState(w, q)) {
            String removed = w.substring(0, q);
            String added = "";
            for (int i = 0; i < q; i++) {
                char c = removed.charAt(i);
                map.put(c, map.getOrDefault(c, 0) - 1);
                if (map.get(c) == 0) {
                    map.remove(c);
                }
            }
            while (!map.isEmpty()) {
                added += map.keySet().iterator().next();
                map.remove(map.keySet().iterator().next());
            }
            w = removed + added;
            time++;
        }

        return time;
    }

    private boolean isInitialState(String w, int q) {
        for (int i = 0; i < w.length(); i++) {
            if (i % (q + 1) != 0) {
                continue;
            }
            String removed = w.substring(i - q, i);
            String added = w.substring(i, i + q);
            if (!removed.equals(added)) {
                return false;
            }
        }
        return true;
    }
}

