public class Solution {
    public long largestSquareArea(int[][] bottomLeft, int[][] topRight) {
        Arrays.sort(bottomLeft, (a, b) -> a[0] - b[0]);
        Arrays.sort(topRight, (a, b) -> a[0] - b[0]);

        int n = bottomLeft.length;
