import java.util.PriorityQueue;

public class Solution {
    public int networkBecomesIdle(int[][] edges, int[] pat) {
        int n = edges.length;
        boolean[] visited = new boolean[n];
        ArrayList<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] edge : edges) {
            graph[edge[0]].add(edge[1]);
            graph[edge[1]].add(edge[0]);
        }

        int[] time = new int[n];
        Arrays.fill(time, -1);
        time[0] = 0;
        PriorityQueue<Integer> pq = new PriorityQueue<>();
        pq.offer(0);

        while (!pq.isEmpty()) {
            int node = pq.poll();
            for (int neighbor : graph[node]) {
                if (time[neighbor] == -1) {
                    time[neighbor] = time[node] + 2;
                    pq.offer(time[neighbor]);
                } else if (time[neighbor] > time[node] + 2) {
                    time[neighbor] = time[node] + 2;
                    pq.offer(time[neighbor]);
                }
            }
        }

        int maxTime = 0;
        for (int i = 1; i < n; i++) {
            if (time[i] > maxTime) {
                maxTime = time[i];
            }
        }

        return maxTime + pat[0];
    }
}

