import java.util.Set;

public class Solution {
    // 0: rook, queen, bishop
    public int countCombinations(String[] pieces, int[][] positions) {
        Set<String> visited = new HashSet<>();
        return dfs(pieces, positions, 0, visited);
    }

    private int dfs(String[] pieces, int[][] positions, int index, Set<String> visited) {
        if (index == pieces.length) {
            return 1;
        }
        int res = 0;
        for (int i = 0; i < 8; i++) {
            for (int j = 0; j < 8; j++) {
                if (!isValidMove(pieces[index], positions[index][0], positions[index][1], i, j)) continue;
                int[][] newPositions = copyArray(positions);
                newPositions[index] = new int[]{i, j};
                res += dfs(pieces, newPositions, index + 1, visited);
            }
        }
        return res;
    }

    private boolean isValidMove(String piece, int r1, int c1, int r2, int c2) {
        if (piece.equals("rook")) {
            return Math.abs(r1 - r2) <= 1 && Math.abs(c1 - c2) <= 1;
        } else if (piece.equals("queen")) {
            return Math.abs(r1 - r2) <= 1 || Math.abs(c1 - c2) <= 1 || Math.abs(r1 - r2) == Math.abs(c1 - c2);
        } else {
            return Math.abs(r1 - r2) == Math.abs(c1 - c2);
        }
    }

    private int[][] copyArray(int[][] array) {
        int[][] result = new int[array.length][];
        for (int i = 0; i < array.length; i++) {
            result[i] = array[i].clone();
        }
        return result;
    }
}

