                int newCol = path[path.length - 1][1] + direction[1];
                if (newRow >= 0 && newRow < rowCosts.length && newCol >= 0 && newCol < colCosts.length) {
                    int newCost = direction[0] == 0 ? colCosts[newCol] : rowCosts[newRow];
                    path = Arrays.copyOf(path, path.length + 1);
                    path[path.length - 1] = new int[]{newRow, newCol};
                    cost += newCost;
                    break;
                }
            }
        }
        return cost;
    }
}

