public class Solution {
    public int minimizedMaximum(int n, int[] q) {
        Arrays.sort(q);
        int left = 1;
        int right = q[q.length - 1];

        while (left <= right) {
            int mid = left + (right - left) / 2;

            if (canDistribute(n, q, mid)) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }

        return left;
    }

    public boolean canDistribute(int n, int[] q, int maxPerStore) {
        int storeCount = 0;
        int totalProducts = 0;

        for (int quantity : q) {
            totalProducts += quantity;

            while (totalProducts > maxPerStore && storeCount < n - 1) {
                totalProducts -= maxPerStore;
                storeCount++;
            }
        }

        return totalProducts <= maxPerStore || storeCount >= n;
    }
}

