public class Solution {
    public int waysToPartition(int[] nums, int k) {
        long leftSum = 0;
        Map<Integer, Long> sumMap = new HashMap<>();
        for (int i = 0; i < nums.length; i++) {
            leftSum += nums[i];
            if (!sumMap.containsKey(leftSum)) {
                sumMap.put(leftSum, (long) i);
            }
        }

        int maxWays = 0;
        long rightSum = 0;
        for (int i = nums.length - 1; i >= 0; i--) {
            rightSum += nums[i];
            if (sumMap.containsKey(rightSum)) {
                int pivot = sumMap.get(rightSum);
                if (pivot < i) {
                    maxWays = Math.max(maxWays, i - pivot + 1);
                }
            }

            if (rightSum > k * (nums.length - i)) {
                break;
            }
        }

        return maxWays;
    }
}

