public class Solution {
    public int countMaxOrSubsets(int[] nums) {
        int maxOr = 0;
        for (int num : nums) {
            maxOr |= num;
        }

        int res = 0;
        Set<Integer> subsets = new HashSet<>();
        backtrack(nums, 0, maxOr, subsets);

        for (Integer subset : subsets) {
            if ((subset & maxOr) == maxOr) {
                res++;
            }
        }

        return res;
    }

    private void backtrack(int[] nums, int start, int maxOr, Set<Integer> subsets) {
        subsets.add(maxOr);
        for (int i = start; i < nums.length; i++) {
            maxOr |= nums[i];
            backtrack(nums, i + 1, maxOr, subsets);
            maxOr ^= nums[i];
        }
    }
}

