import java.util.ArrayDeque;
import java.util.HashSet;

public class Solution {
    public int scoreOfStudents(String s, int[] answers) {
        int n = answers.length;
        int totalPoints = 0;

        for (int answer : answers) {
            int points = 0;

            // Check if the answer is correct
            if (answer == eval(s)) {
                points = 5;
            } else {
                // Check if the answer could be interpreted as if the student applied the operators in the wrong order but had correct arithmetic
                String[] parts = s.split("(?=[0-9]+)|(?<=[+*])");
                int prev = Integer.parseInt(parts[0]);

                for (int i = 1; i < parts.length - 1; i++) {
                    if (parts[i].equals("+")) {
                        if ((prev + Integer.parseInt(parts[i + 1])) == answer) {
                            points = 2;
                            break;
                        }
                    } else {
                        if ((prev * Integer.parseInt(parts[i + 1])) == answer) {
                            points = 2;
                            break;
                        }
                    }
                    prev = (parts[i].equals("+")) ? prev + Integer.parseInt(parts[i + 1]) : prev * Integer.parseInt(parts[i + 1]);
                }

                // If the answer is not correct and cannot be interpreted as if the student applied the operators in the wrong order but had correct arithmetic, then it's 0 points
                if (points == 0) {
                    totalPoints += 0;
                } else {
                    totalPoints += points;
                }
            }
        }

        return totalPoints;
    }

    public int eval(String s) {
        ArrayDeque<String> stack = new ArrayDeque<>();
        HashSet<Character> operators = new HashSet<>(Arrays.asList('+', '*'));

        for (char c : s.toCharArray()) {
            if (Character.isDigit(c)) {
                stack.push(String.valueOf(c));
            } else if (operators.contains(c)) {
                String num1 = stack.pop();
                String op = String.valueOf(c);
                String num2 = "";

                while (!stack.isEmpty() && Character.isDigit(stack.peek().charAt(0))) {
                    num2 += stack.pop();
                }

                if (!num2.isEmpty()) {
                    stack.push(num2);
                }

                stack.push("(" + num1 + op + (num2.isEmpty() ? "" : num2) + ")");
            }
        }

        return Integer.parseInt(stack.pop());
    }
}

