public class Solution {
    public int maxProduct(String s) {
        int n = s.length();
        boolean[][] dp = new boolean[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = i; j < n; j++) {
                if (s.charAt(i) == s.charAt(j) && ((i + 1 <= j - 1) || !dp[i + 1][j - 1])) {
                    dp[i][j] = true;
                }
            }
        }

        int maxProduct = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i; j < n; j++) {
                if (!dp[i][j]) {
                    int product = 1;
                    for (int k = i; k <= j; k++) {
                        product *= (s.charAt(k) == '0' ? 1 : 2);
                    }
                    maxProduct = Math.max(maxProduct, product);
                }
            }
        }

        return maxProduct;
    }
}

