import java.util.ArrayList;
import java.util.List;

public class Solution {
    public long kMirror(int k, int n) {
        List<Long> result = new ArrayList<>();
        for (int i = 1; ; i++) {
            String base10 = Long.toString(i);
            if (!isKMirror(k, base10)) {
                continue;
            }
            if (result.size() >= n) {
                long sum = 0;
                for (Long num : result) {
                    sum += num;
                }
                return sum;
            }
            result.add(Long.parseLong(getBaseK(i, k)));
        }
    }

    private boolean isKMirror(int k, String base10) {
        if (!base10.equals(new StringBuilder(base10).reverse().toString())) {
            return false;
        }
        return true;
    }

    private String getBaseK(long num, int k) {
        StringBuilder sb = new StringBuilder();
        while (num > 0) {
            long remainder = num % k;
            if (remainder >= 10) {
                sb.append((char) ('A' + remainder - 10));
            } else {
                sb.append(remainder);
            }
            num /= k;
        }
        return new StringBuilder(sb.reverse().toString()).reverse().toString();
    }
}

