public class Solution {
    public int[] platesBetweenCandles(String s, int[][] queries) {
        List<Integer> plateCounts = new ArrayList<>();
        int totalPlates = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '|') {
                totalPlates++;
            } else {
                plateCounts.add(totalPlates);
                totalPlates = 0;
            }
        }
        int[] answer = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int left = queries[i][0];
            int right = queries[i][1];
            if (s.charAt(left) == '|') {
                answer[i] = plateCounts.get(right - left + 1);
            } else {
                for (int j = left; j <= right; j++) {
                    if (s.charAt(j) == '|') {
                        totalPlates++;
                    } else {
                        totalPlates--;
                    }
                }
                answer[i] = totalPlates;
            }
        }
        return answer;
    }
}

