import com_github_leetcode.ListNode;

public class Solution {
    public int[] nodesBetweenCriticalPoints(ListNode head) {
        ListNode current = head;
        int minDistance = Integer.MAX_VALUE, maxDistance = 0;
        boolean isCriticalPoint = false;

        while (current != null) {
            if ((current.next == null || current.val <= current.next.val) && 
                (current.prev == null || current.val >= current.prev.val)) {
                if (!isCriticalPoint) {
                    minDistance = 1;
                    isCriticalPoint = true;
                } else {
                    maxDistance = Math.max(maxDistance, current.val - head.val);
                    minDistance = Math.min(minDistance, current.val - head.val);
                }
            } else {
                isCriticalPoint = false;
            }
            current = current.next;
        }

        if (minDistance == Integer.MAX_VALUE) return new int[]{-1, -1};
        return new int[]{minDistance - 1, maxDistance};
    }
}

