public class Solution {
    public int countPyramids(int[][] grid) {
        int m = grid.length, n = grid[0].length, res = 0;
        Map<Integer, Integer> left = new HashMap<>();
        for (int i = 0; i < m; i++) {
            int ones = 0;
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) ones++;
            }
            res += ones * (ones - 1) / 2;
            left.put(i, ones);
        }
        Map<Integer, Integer> right = new HashMap<>();
        for (int i = m - 1; i >= 0; i--) {
            int ones = 0;
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) ones++;
            }
            res += ones * (ones - 1) / 2;
            right.put(i, ones);
        }
        for (Map.Entry<Integer, Integer> entry : left.entrySet()) {
            int i = entry.getKey(), ones = entry.getValue();
            if (right.containsKey(i)) {
                res -= ones * right.get(i);
            }
        }
        return res;
    }
}

