import com_github_leetcode.TreeNode;

public class Solution {
    public String findShortestPath(TreeNode root, int s, int t) {
        Map<Integer, TreeNode> map = new HashMap<>();
        Queue<TreeNode> queue = new LinkedList<>();
        StringBuilder sb = new StringBuilder();
        boolean found = false;

        if (root == null || root.val != s) return "";

        map.put(root.val, root);
        queue.offer(root);

        while (!queue.isEmpty()) {
            TreeNode node = queue.poll();

            if (node.val == t) {
                found = true;
                break;
            }

            if (node.left != null && !map.containsKey(node.left.val)) {
                map.put(node.left.val, node.left);
                queue.offer(node.left);
            }

            if (node.right != null && !map.containsKey(node.right.val)) {
                map.put(node.right.val, node.right);
                queue.offer(node.right);
            }

            if (node.parent != null && !map.containsKey(node.parent.val)) {
                map.put(node.parent.val, node.parent);
                queue.offer(node.parent);
            }
        }

        TreeNode current = map.get(t);
        while (current.val != s) {
            if (current == map.get(s).parent) sb.insert(0, 'U');
            else if (current.val > current.parent.val) sb.insert(0, 'R');
            else sb.insert(0, 'L');
            current = current.parent;
        }

        return found ? sb.toString() : "";
    }
}

