import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedList;
import java.util.List;
import java.util.Queue;

public class Solution {
    public int secondMinimum(int n, int[][] edges, int time, int change) {
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i <= n; i++) {
            graph.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            graph.get(edge[0]).add(edge[1]);
            graph.get(edge[1]).add(edge[0]);
        }

        int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        boolean[][] visited = new boolean[n + 1][n + 1];
        int[] timeArr = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            timeArr[i] = time;
        }

        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{1, time});
        visited[1][time % change] = true;

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            for (int[] dir : directions) {
                int x = cur[0] + dir[0];
                int y = cur[1] + dir[1];
                if (x >= 1 && x <= n && y >= 0 && y < change) {
                    if (!visited[x][y]) {
                        visited[x][y] = true;
                        queue.offer(new int[]{x, y});
                    }
                } else if (x >= 1 && x <= n && y >= change) {
                    if (!visited[x][(y - change + time) % change]) {
                        visited[x][(y - change + time) % change] = true;
                        queue.offer(new int[]{x, (y - change + time) % change});
                    }
                }
            }
        }

        for (int i = 1; i <= n; i++) {
            if (!visited[i][timeArr[i]]) {
                return -1;
            }
        }

        int minTime = Integer.MAX_VALUE;
        for (int i = 1; i <= n; i++) {
            minTime = Math.min(minTime, timeArr[i]);
        }

        int secondMinTime = Integer.MAX_VALUE;
        for (int i = 1; i <= n; i++) {
            if (timeArr[i] > minTime) {
                secondMinTime = Math.min(secondMinTime, timeArr[i]);
            }
        }

        return secondMinTime;
    }
}

